import helmet from "helmet";
import rateLimit from "express-rate-limit";
import { diffLines } from "diff";

const execFileAsync = promisify(execFile);

const app = express();

// ============================================================================
// COMPREHENSIVE LOGGING TO FILE AND CONSOLE
// ============================================================================

/**
 * LOG ALL MESSAGES TO BOTH CONSOLE AND FILE
 *
 * WHY THIS IS CRITICAL:
 *  - Backend logs go to stdout in terminal (AI assistant can't access it)
 *  - Writing to /tmp/vlc-debug.log allows AI to read ALL messages verbatim
 *  - User requested: "capturing and displaying _all_ messages instead of llm recalcitrance"
 *  - User emphasized: "nearly 100% troubleshooting success rate" with this approach
 *
 * WHAT GETS LOGGED:
 *  - ALL yt-dlp stdout messages (download progress, completion, etc.)
 *  - ALL yt-dlp stderr messages (warnings, errors)
 *  - ALL file polling checks (every 500ms)
 *  - ALL file size measurements
 *  - ALL threshold calculations
 *  - ALL launch decisions (why player launched or didn't launch)
 *  - ALL player spawn/exit events
 *
 * FORMAT:
 *  - Timestamp (ISO 8601) for chronological ordering
 *  - Download ID for correlation
 *  - Message text (verbatim, no filtering)
 *
 * USAGE:
 *  logBoth(downloadId, message) - logs to console and file
 */
const DEBUG_LOG_FILE = "/tmp/vlc-debug.log";

function logBoth(downloadId, message) {
  const timestamp = new Date().toISOString();
  const logLine = `[${timestamp}] [download-${downloadId}] ${message}\n`;

  // Write to console (for user's terminal)
  console.log(`[download-${downloadId}] ${message}`);

  // Write to file (for AI assistant to read)
  try {
    appendFileSync(DEBUG_LOG_FILE, logLine);
  } catch (err) {
    console.error(`[download-${downloadId}] FAILED TO WRITE DEBUG LOG: ${err.message}`);
  }
}

// ============================================================================
// ACTIVE DOWNLOAD REGISTRY
// ============================================================================

/**
 * ACTIVE DOWNLOAD REGISTRY
 *
 * Purpose: Track all in-progress YouTube downloads for:
 *  - Resume support (continue partial downloads after interruption)
 *  - Cancellation (kill yt-dlp process on user request)
 *  - Progress tracking (real-time download percentage)
 *  - Stall detection (identify stuck downloads)
 *
 * Data structure:
 *  Map<downloadId, {
 *    process: ChildProcess,      // yt-dlp process handle
 *    progress: number,            // Download percentage (0-100)
 *    filePath: string,            // Absolute path to MP4 file
 *    lastUpdate: number,          // Timestamp of last progress update
 *    url: string,                 // Original YouTube URL
 *    playerPid: number|null       // MPV/VLC process ID (if launched)
 *  }>
 *
 * Why Map instead of Object:
 *  - Faster iteration for stall detection
 *  - Cleaner API (has/get/set/delete)
 *  - No prototype pollution risk
 *
 * Lifecycle:
 *  1. Entry created when download starts
 *  2. Updated every time yt-dlp emits progress
 *  3. Deleted when download completes or is cancelled
 */
const activeDownloads = new Map();

// === SECURITY BASELINE (OWASP + Express best practices) ===
app.disable("x-powered-by");
app.use(helmet({ contentSecurityPolicy: false })); // CSP off — Vite injects inline scripts in dev
app.use(express.json({ limit: "1mb" }));

const limiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute window
  max: 60, // 60 requests per minute per IP
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: "Too many requests, try again later" },
});
app.use("/api/", limiter);

