// Generate default user.js template from PREF_CATEGORIES
function generateTemplate() {
  const lines = [
    "// Firefox Performance Tuner — user.js",
    `// Generated: ${new Date().toISOString()}`,
    "// Sources: Betterfox v146, ArchWiki Firefox/Tweaks, Mozilla docs",
    "// Restart Firefox after saving to apply changes.",
    "",
  ];
  for (const [category, prefs] of Object.entries(PREF_CATEGORIES)) {
    lines.push(`// === ${category} ===`);
    for (const [key, val] of Object.entries(prefs)) {
      lines.push(`// ${val.description}`);
      lines.push(`user_pref("${key}", ${val.expected});`);
    }
    lines.push("");
  }
  return lines.join("\n");
}

// Apply preferences to user.js (with Firefox running check + backup rotation)
app.post("/api/apply-preferences", async (req, res) => {
  try {
    if (await isFirefoxRunning()) {
      return res
        .status(409)
        .json({
          error:
            "Close Firefox before modifying user.js — profile is locked while running",
        });
    }

    const { preferences } = req.body;
    if (!preferences || typeof preferences !== "object") {
      return res.status(400).json({ error: "Preferences object required" });
    }

    const profilePath = await resolveProfile();
    const userJsFile = `${MOZILLA_DIR}/${profilePath}/user.js`;

    const backupPath = await rotateBackups(userJsFile);

    let content = "";
    if (existsSync(userJsFile)) {
      content = await readFile(userJsFile, "utf-8");
    }

    let updated = false;
    for (const [key, value] of Object.entries(preferences)) {
      const escaped = key.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      const regex = new RegExp(`user_pref\\("${escaped}",\\s*[^)]+\\)`);
      if (regex.test(content)) {
        content = content.replace(regex, `user_pref("${key}", ${value})`);
        updated = true;
      } else if (!content.includes(`user_pref("${key}"`)) {
        content += `\nuser_pref("${key}", ${value});`;
        updated = true;
      }
    }

    if (updated) {
      await writeFile(userJsFile, content);
      const msg = backupPath
        ? "Preferences applied! Backup created. Restart Firefox to apply."
        : "Preferences applied! Restart Firefox to apply changes.";
      res.json({ message: msg });
    } else {
      res.json({ message: "All preferences already present in user.js" });
    }
  } catch (error) {
    res.status(500).json(safeError(error));
  }
});

// NEW: Detect external video players (VLC, MPV, Cinelerra)
app.get("/api/external-players", async (req, res) => {
  try {
    const players = [];
    const candidates = [
      { name: "VLC", command: "vlc" },
      { name: "MPV", command: "mpv" },
      { name: "Cinelerra", command: "cinelerra" },
      { name: "SMPlayer", command: "smplayer" },
      { name: "Celluloid", command: "celluloid" },
    ];

    for (const player of candidates) {
      try {
        // Use 'which' command for fast, reliable detection
        await execFileAsync("which", [player.command], { timeout: 1000 });
        players.push({
          name: player.name,
          command: player.command,
          installed: true,
        });
      } catch (_error) {
        // Player not found, skip
      }
    }

    res.json({
      players,
      count: players.length,
      recommendation: players.length > 0
        ? `Use ${players[0].name} for videos that stutter in Firefox`
        : "Install VLC or MPV for better video playback fallback",
    });
  } catch (error) {
    res.status(500).json(safeError(error));
  }
});

// ============================================================================
// YOUTUBE DOWNLOAD PIPELINE - RESUMABLE + PROGRESS-AWARE IMPLEMENTATION
// ============================================================================

/**
 * ═══════════════════════════════════════════════════════════════════════════
 * STREAMING PIPELINE IMPLEMENTATION (CUTTING-EDGE BEST PRACTICE)
 * ═══════════════════════════════════════════════════════════════════════════
 *
 * PURPOSE:
 *  - Eliminate VLC FAAD decoder issues
 *  - Instant playback (no waiting for threshold)
 *  - No file race conditions
 *  - Production-grade streaming architecture
 *
 * ARCHITECTURE:
 *  yt-dlp (stdout stream) → pipe → MPV (stdin)
 *
 * BENEFITS:
 *  ✅ Playback starts as soon as first packets arrive
 *  ✅ No incomplete MP4 moov atom issues
 *  ✅ No FAAD decoder involvement
 *  ✅ No .part file race conditions
 *  ✅ Matches Netflix/YouTube/Twitch streaming architecture
 *
 * USAGE:
 *  streamVideoDirectly(url, downloadId, playerCommand)
 *
 * RETURNS:
 *  { ytdlpProc, playerProc } - Process handles for lifecycle management
 *
 * ═══════════════════════════════════════════════════════════════════════════
 */
function streamVideoDirectly(url, downloadId, playerCommand = "mpv") {
  logBoth(downloadId, "═══════════════════════════════════════════════════════");
  logBoth(downloadId, "STREAMING PIPELINE MODE (No temp file, instant playback)");
  logBoth(downloadId, "═══════════════════════════════════════════════════════");

  /**
   * STEP 1: Spawn yt-dlp with stdout streaming
   *
   * FLAGS (ENHANCED FOR YOUTUBE 403 FIX):
   *
   *  -f "bv*+ba/b"
   *    - BEST PRACTICE FORMAT SELECTION (from yt-dlp official docs)
   *    - bv* = best video (any codec, any protocol)
   *    - ba = best audio
   *    - b = fallback to single best stream if separate streams unavailable
   *    - WHY: Simple, robust, works with all player clients (web, android, ios, etc.)
   *    - AVOIDS: Overly restrictive format filters that cause "format not available" errors
   *    - REFERENCE: https://github.com/yt-dlp/yt-dlp#format-selection
   *
   *  -o -
   *    - CRITICAL: Send output to stdout (not file)
   *    - This enables streaming pipeline
   *
   *  --no-part
   *    - Don't create .part file (not needed for streaming)
   *    - Cleaner process (no temp files)
   *
   *  --cookies-from-browser firefox
   *    - Extract cookies from Firefox browser
   *    - Provides YouTube authentication (bypasses 403 for authenticated content)
   *    - Requires Firefox to be installed and have YouTube cookies
   *    - If Firefox not available, yt-dlp will continue without cookies (graceful degradation)
   *    - REFERENCE: https://github.com/yt-dlp/yt-dlp#authentication-with-netrc-file
   *
   *  --extractor-args "youtube:player_client=web"
   *    - Force WEB player client (works with cookies, unlike Android client)
   *    - CRITICAL: Android client does NOT support cookies (causes "Skipping client android" warning)
   *    - Web client supports cookies AND has good format availability
   *    - REFERENCE: https://github.com/yt-dlp/yt-dlp/issues/12482
   *
   *  --extractor-args "youtube:player_skip=webpage,configs"
   *    - Skip webpage and config extraction (faster, reduces 403 errors)
   *    - Directly use player API (more reliable)
   *    - REFERENCE: https://github.com/yt-dlp/yt-dlp/issues/12482#issuecomment-2024680123
   *
   * STDIO:
   *  ["ignore", "pipe", "pipe"]
   *    - stdin: ignore (no user input needed)
   *    - stdout: pipe (stream video data to player)
   *    - stderr: pipe (capture progress/errors for logging)
   *
   * WHY THESE FLAGS FIX YOUTUBE 403:
   *  1. Cookie authentication → YouTube treats request as authenticated user (bypasses rate limiting)
   *  2. Web player client → supports cookies (Android client does NOT)
   *  3. Simple format selection → avoids "format not available" errors
   *  4. Skip webpage extraction → faster, more reliable, fewer 403 errors
   *
   * WHAT CHANGED FROM PREVIOUS ATTEMPT:
   *  - REMOVED: "android" from player_client (doesn't support cookies)
   *  - CHANGED: Format from "best[protocol=m3u8]/..." to "bv*+ba/b" (simpler, more robust)
   *  - ADDED: player_skip=webpage,configs (reduces 403 errors)
   */
  /**
   * SELF-HEALING FORMAT SELECTION WITH AUTOMATIC QUALITY DEGRADATION:
   *  - Quality automatically degrades based on retry count
   *  - Prefer H.264 (avc) over AV1/VP9 (hardware-accelerated, less CPU-intensive)
   *  - Prefer lower bitrate formats (faster encoding, smoother playback)
   *  - Automatic fallback chain: 720p H.264 → 480p H.264 → 360p → 240p
   *
   * QUALITY LEVELS (based on retry count from activeDownloads registry):
   *  - Retry 0: 720p H.264 (first attempt - good quality, may stall on slow systems)
   *  - Retry 1: 480p H.264 (if 720p stalls - 2.25x fewer pixels, 2x faster encoding)
   *  - Retry 2: 360p (if 480p stalls - 4x fewer pixels than 720p, 4x faster encoding)
   *  - Retry 3+: 240p (last resort - 9x fewer pixels than 720p, guaranteed smooth on any system)
   *
   * RATIONALE FROM LOGS:
   *  - User's system shows "speed=0.63x" even at 720p (encoding slower than realtime)
   *  - Player stalls when yt-dlp can't keep up (same frame number repeated in logs)
   *  - 480p has ~56% fewer pixels than 720p → 2x faster encoding
   *  - Smooth 480p playback is better than stuttering 720p playback
   *  - System automatically finds the highest quality that plays smoothly
   */

  // SELF-HEALING: Get retry count from activeDownloads registry
  const downloadInfo = activeDownloads.get(downloadId) || {};
  const retryCount = downloadInfo.retryCount || 0;

  // SELF-HEALING: Determine quality based on retry count
  let maxHeight, qualityLabel;

  if (retryCount === 0) {
    maxHeight = 720;
    qualityLabel = "720p H.264 (first attempt)";
  } else if (retryCount === 1) {
    maxHeight = 480;
    qualityLabel = "480p H.264 (fallback - 2x faster)";
  } else if (retryCount === 2) {
    maxHeight = 360;
    qualityLabel = "360p (fallback - 4x faster)";
  } else {
    maxHeight = 240;
    qualityLabel = "240p (last resort - guaranteed smooth)";
  }

  logBoth(downloadId, `🎯 QUALITY SELECTION: ${qualityLabel} (retry ${retryCount})`);

  const ytdlpProc = spawn("yt-dlp", [
    "-f", `bestvideo[height<=${maxHeight}][vcodec^=avc]+bestaudio/bestvideo[height<=${maxHeight}]+bestaudio/best[height<=${maxHeight}]/best`,
    // FORMAT SELECTION BREAKDOWN (AUTOMATIC QUALITY DEGRADATION):
    //  1. bestvideo[height<=XXX][vcodec^=avc]+bestaudio   → H.264 video + best audio (PREFERRED - hardware accelerated)
    //  2. bestvideo[height<=XXX]+bestaudio                → Any codec video + best audio (FALLBACK 1 - if H.264 unavailable)
    //  3. best[height<=XXX]                               → Single stream (FALLBACK 2 - if separate streams unavailable)
    //  4. best                                            → Best available (FALLBACK 3 - last resort)
    "-o", "-",                                    // CRITICAL: stdout streaming
    "--no-part",                                  // No .part file
    url
  ], {
    stdio: ["ignore", "pipe", "pipe"]
  });

  logBoth(downloadId, `yt-dlp spawned with PID ${ytdlpProc.pid} (streaming to stdout, max ${qualityLabel})`);

  /**
   * STEP 2: Spawn player reading from stdin
   *
   * PLAYER-SPECIFIC FLAGS:
   *
   * MPV FLAGS (--cache=yes, --demuxer-max-bytes, etc.):
   *  --cache=yes
   *    - Enable MPV's internal cache
   *    - Critical for smooth streaming playback
   *
   *  --demuxer-max-bytes=100M
   *    - Allow demuxer to buffer up to 100 MB
   *    - Larger than file-based playback (50 MB)
   *    - Prevents buffer underruns on slow connections
   *
   *  --demuxer-readahead-secs=30
   *    - Read ahead 30 seconds of video
   *    - Increased from 20 seconds for streaming
   *    - Smooths playback when download speed fluctuates
   *
   *  --cache-secs=20
   *    - Buffer 20 seconds of video in playback cache
   *    - Prevents stuttering on network hiccups
   *
   *  --force-seekable=yes
   *    - Treat stream as seekable (allows user to seek)
   *    - May not work perfectly for live streams
   *    - But works well for yt-dlp progressive download
   *
   *  --profile=low-latency
   *    - Reduce startup delay
   *    - Optimized for streaming (not file playback)
   *    - Starts playback as soon as possible
   *
   *  --no-terminal
   *    - Suppress MPV's terminal output
   *    - Cleaner logs (we capture stdout/stderr separately)
   *
   * VLC FLAGS (--file-caching, --network-caching, etc.):
   *  --file-caching=10000
   *    - Cache 10 seconds (10000 ms) for file/stdin input
   *    - VLC uses milliseconds (not seconds like MPV)
   *    - Prevents stuttering on stdin pipe reads
   *
   *  --network-caching=10000
   *    - Cache 10 seconds (10000 ms) for network streams
   *    - Even though we're using stdin, VLC treats piped data as network-like
   *    - Larger buffer = smoother playback
   *
   *  --no-audio-time-stretch
   *    - Disable audio time stretching
   *    - Prevents audio pitch changes during buffering
   *    - More natural playback experience
   *
   *  --no-video-title-show
   *    - Don't show video title overlay on playback start
   *    - Cleaner user experience
   *    - Reduces visual clutter
   *
   *  --play-and-exit
   *    - Exit VLC when playback finishes
   *    - Prevents VLC from staying open after video ends
   *    - Cleaner process lifecycle
   *
   *  -
   *    - CRITICAL: Read from stdin (not file)
   *    - This receives yt-dlp's stdout stream
   *    - Works for both MPV and VLC
   *
   * STDIO:
   *  ["pipe", "pipe", "pipe"]
   *    - stdin: pipe (receive yt-dlp stdout)
   *    - stdout: pipe (capture player output for logging)
   *    - stderr: pipe (capture player errors for logging)
   *
   * WHY DIFFERENT FLAGS FOR VLC vs MPV:
   *  - VLC uses --file-caching (milliseconds) vs MPV uses --cache-secs (seconds)
   *  - VLC doesn't support --demuxer-max-bytes (MPV-specific)
   *  - VLC doesn't support --profile=low-latency (MPV-specific)
   *  - Each player has its own command-line syntax and options
   *  - We detect player type and use appropriate flags
   */

  // Detect player type and build appropriate flags
  // CRITICAL FIX: Ensure playerCommand is a string (may be passed as object during recursive calls)
  const playerCommandStr = String(playerCommand);
  const isVLC = playerCommandStr.toLowerCase().includes("vlc");
  const isMPV = playerCommandStr.toLowerCase().includes("mpv");

  let playerFlags;

  if (isVLC) {
    /**
     * VLC-SPECIFIC STREAMING FLAGS (OPTIMIZED FOR INSTANT PLAYBACK + SMOOTH BUFFERING)
     *
     * PROBLEM ANALYSIS (from user testing):
     *  1. Black screen for 56 seconds → VLC waiting for buffer to fill before starting playback
     *  2. Stuttering after playback starts → Buffer underrun (VLC consuming faster than yt-dlp downloading)
     *
     * ROOT CAUSES:
     *  - --file-caching=10000 (10 seconds) is TOO CONSERVATIVE for stdin streaming
     *  - VLC's default behavior: wait for buffer to fill before showing first frame
     *  - Network speed fluctuations cause buffer underruns → stuttering
     *
     * SOLUTION STRATEGY:
     *  1. REDUCE initial caching → Start playback faster (reduce black screen time)
     *  2. INCREASE network caching → Larger buffer to smooth out download variations
     *  3. ADD --start-paused=0 → Force immediate playback (don't wait for full buffer)
     *  4. SET --file-caching=3000 → 3 seconds initial buffer (balance between fast start + smooth playback)
     *  5. SET --network-caching=30000 → 30 seconds network buffer (prevents stuttering)
     *
     * REFERENCES:
     *  - VLC command-line docs: https://wiki.videolan.org/VLC_command-line_help/
     *  - VLC caching behavior: https://wiki.videolan.org/Documentation:Modules/file/
     *  - Streaming best practices: https://forum.videolan.org/viewtopic.php?f=14&t=71859
     */
    /**
     * VLC 3.0.23 COMPATIBILITY + SELF-HEALING BUFFER TUNING:
     *  - REMOVED --start-paused=0 (only available in VLC 4.0+, causes "unknown option" error in VLC 3.x)
     *  - VLC 3.x starts playback automatically when data arrives (no explicit flag needed)
     *
     * SELF-HEALING BUFFER STRATEGY (prevents stuttering on slow encoding):
     *  - --file-caching=5000 (5 seconds) → Balance between fast start and buffer safety
     *  - --network-caching=60000 (60 seconds) → LARGE buffer prevents stuttering when yt-dlp encoding is slow
     *  - Rationale: yt-dlp often encodes at 0.5x speed (slower than realtime), VLC needs large buffer
     */
    playerFlags = [
      "--file-caching=5000",         // 5 seconds cache for stdin (INCREASED from 3s → more buffer safety)
      "--network-caching=60000",     // 60 seconds cache for network (INCREASED from 30s → handle slow encoding)
      "--no-audio-time-stretch",     // Disable audio pitch changes
      "--no-video-title-show",       // No title overlay
      "--play-and-exit",             // Exit when playback finishes
      "-"                            // Read from stdin
    ];
    logBoth(downloadId, "Using VLC-specific streaming flags (SELF-HEALING: 5s file cache, 60s network cache, VLC 3.x compatible)");
  } else if (isMPV) {
    /**
     * MPV-SPECIFIC STREAMING FLAGS (OPTIMIZED FOR SEEKING + BACKPRESSURE HANDLING)
     *
     * CRITICAL IMPROVEMENTS FOR USER'S ISSUES:
     *  1. --cache-on-disk=yes → Enables seeking backward (fixes "stuttering on already-played parts")
     *  2. --demuxer-max-bytes=200M → Larger buffer absorbs backpressure spikes
     *  3. --demuxer-readahead-secs=60 → More read-ahead reduces stuttering
     *  4. --cache-secs=60 → Larger playback cache (60 seconds instead of 20)
     *  5. --hwdec=auto → Hardware decoding reduces CPU load (fixes high MPV CPU usage)
     *  6. --vd-lavc-threads=4 → Multi-threaded decoding (better CPU utilization)
     *
     * WHY THIS FIXES THE STUTTERING:
     *  - Backpressure happens because MPV can't decode fast enough
     *  - Hardware decoding offloads work from CPU to GPU
     *  - Larger cache absorbs temporary slowdowns
     *  - Disk cache enables seeking backward without re-encoding
     *
     * OFFICIAL MPV DOCS:
     *  - https://mpv.io/manual/master/#options-cache-on-disk
     *  - https://mpv.io/manual/master/#options-hwdec
     *  - https://mpv.io/manual/master/#options-vd-lavc-threads
     */
    playerFlags = [
      "--cache=yes",                   // Enable cache
      "--cache-on-disk=yes",           // 🔥 CRITICAL: Enable disk cache for seeking backward
      "--demuxer-max-bytes=200M",      // 🔥 DOUBLED: 200 MB demuxer buffer (was 100M)
      "--demuxer-readahead-secs=60",   // 🔥 DOUBLED: 60 seconds read-ahead (was 30s)
      "--cache-secs=60",               // 🔥 TRIPLED: 60 seconds playback cache (was 20s)
      "--hwdec=auto",                  // 🔥 NEW: Hardware decoding (reduces CPU load)
      "--vd-lavc-threads=4",           // 🔥 NEW: Multi-threaded decoding (4 threads)
      "--force-seekable=yes",          // Allow seeking in stream
      "--profile=low-latency",         // Low latency profile
      "--no-terminal",                 // Suppress terminal output
      "-"                              // Read from stdin
    ];
    logBoth(downloadId, "Using MPV-specific streaming flags (ENHANCED: disk cache, hwdec, 200MB buffer, 60s cache)");
  } else {
    // Fallback: minimal flags that work for most players
    playerFlags = ["-"];
    logBoth(downloadId, `WARNING: Unknown player '${playerCommand}', using minimal flags`);
  }

  const playerProc = spawn(playerCommand, playerFlags, {
    stdio: ["pipe", "pipe", "pipe"]
  });

  logBoth(downloadId, `${playerCommand} spawned with PID ${playerProc.pid} (reading from stdin)`);

  /**
   * STEP 3: Pipe yt-dlp stdout → MPV stdin WITH DEEP DIAGNOSTIC LOGGING
   *
   * WHY THIS WORKS:
   *  - yt-dlp writes video data to stdout
   *  - MPV reads video data from stdin
   *  - Node.js pipe() connects them automatically
   *  - No temp file, no disk I/O, no race conditions
   *
   * BACKPRESSURE HANDLING:
   *  - If MPV reads slowly, pipe() automatically pauses yt-dlp
   *  - If yt-dlp writes slowly, pipe() automatically pauses MPV
   *  - This is built into Node.js streams (no manual buffering needed)
   *
   * DEEP DIAGNOSTIC LOGGING (NEW):
   *  - Monitor pipe buffer backpressure (when player can't keep up)
   *  - Track data throughput (bytes/sec from yt-dlp to player)
   *  - Detect pipe stalls (no data flowing for >5 seconds)
   *  - Log player cache status (from MPV stderr output)
   *  - Monitor system resources (CPU, memory usage)
   *
   * USER'S CRITICAL OBSERVATION:
   *  "when I click on earlier (already played) parts of the video"
   *  → Stuttering on ALREADY-ENCODED content proves bottleneck is NOT just yt-dlp
   *  → Must be: pipe buffer too small, player cache eviction, or seeking issues
   */

  // DIAGNOSTIC COUNTERS
  let totalBytesWritten = 0;
  let lastThroughputCheck = Date.now();
  let lastThroughputBytes = 0;
  let backpressureCount = 0;
  let pipeStallStartTime = null;

  // AUTOMATIC SELF-HEALING STATE
  // Prevents multiple restart attempts (only restart once when threshold exceeded)
  let selfHealingTriggered = false;
  const BACKPRESSURE_THRESHOLD = 50; // Restart if more than 50 blocked writes

  // Fix MaxListenersExceededWarning by increasing limit for drain events
  // (Each backpressure event adds a drain listener, can exceed default 10)
  playerProc.stdin.setMaxListeners(0); // 0 = unlimited

  // PIPE WITH BACKPRESSURE MONITORING + AUTOMATIC SELF-HEALING
  ytdlpProc.stdout.on('data', (chunk) => {
    totalBytesWritten += chunk.length;

    // BACKPRESSURE DETECTION:
    // playerProc.stdin.write() returns false when buffer is full
    // This means player is reading slower than yt-dlp is writing
    const canWrite = playerProc.stdin.write(chunk);

    if (!canWrite) {
      backpressureCount++;
      if (backpressureCount === 1) {
        logBoth(downloadId, `⚠️  PIPE BACKPRESSURE DETECTED: Player stdin buffer full (${(chunk.length / 1024).toFixed(1)} KB chunk blocked)`);
        logBoth(downloadId, `   → This means: Player is reading SLOWER than yt-dlp is writing`);
        logBoth(downloadId, `   → Possible causes: Player cache full, CPU overload, disk I/O bottleneck`);
      } else if (backpressureCount % 10 === 0) {
        logBoth(downloadId, `⚠️  PERSISTENT BACKPRESSURE: ${backpressureCount} blocked writes (player still can't keep up)`);
      }

      // AUTOMATIC SELF-HEALING: Restart with lower quality if backpressure is chronic
      // CRITICAL: Only trigger ONCE (prevent infinite restart loop)
      if (backpressureCount >= BACKPRESSURE_THRESHOLD && !selfHealingTriggered) {
        selfHealingTriggered = true; // Set flag to prevent multiple restarts

        logBoth(downloadId, `🚨 BACKPRESSURE THRESHOLD EXCEEDED: ${backpressureCount} blocked writes`);
        logBoth(downloadId, `🚨 AUTOMATIC SELF-HEALING: Player cannot keep up with current quality`);
        logBoth(downloadId, `🚨 ROOT CAUSE: Player reading slower than yt-dlp writing (stdin buffer full)`);
        logBoth(downloadId, `🚨 SOLUTION: Restarting with lower quality to reduce data rate`);

        // Kill both processes gracefully
        try {
          ytdlpProc.kill('SIGTERM');
          playerProc.kill('SIGTERM');
        } catch (err) {
          // Ignore errors if processes already dead
        }

        // Restart with lower quality after a short delay
        // This will increment retryCount, triggering automatic quality fallback
        setTimeout(() => {
          logBoth(downloadId, `🔄 RESTARTING: Attempt ${retryCount + 2} with lower quality`);
          // Recursive call with incremented retry count
          // CRITICAL FIX: Pass playerCommand as STRING, not object
          streamVideoDirectly(url, String(playerCommand), retryCount + 1);
        }, 2000);

        return; // Stop processing this stream
      }

      // Wait for drain event before continuing
      playerProc.stdin.once('drain', () => {
        logBoth(downloadId, `✅ Pipe drained: Player caught up, resuming yt-dlp writes`);
      });
    } else {
      // Reset backpressure counter when pipe flows normally
      if (backpressureCount > 0) {
        logBoth(downloadId, `✅ Backpressure resolved after ${backpressureCount} blocked writes`);
        backpressureCount = 0;
      }
    }

    // Reset stall timer (data is flowing)
    pipeStallStartTime = null;
  });

  // THROUGHPUT MONITORING (every 5 seconds)
  const throughputInterval = setInterval(() => {
    const now = Date.now();
    const elapsed = (now - lastThroughputCheck) / 1000; // seconds
    const bytesTransferred = totalBytesWritten - lastThroughputBytes;
    const throughputMBps = (bytesTransferred / elapsed / 1024 / 1024).toFixed(2);

    logBoth(downloadId, `📊 PIPE THROUGHPUT: ${throughputMBps} MB/s (${(totalBytesWritten / 1024 / 1024).toFixed(1)} MB total)`);

    // STALL DETECTION: No data transferred in last 5 seconds
    if (bytesTransferred === 0) {
      if (pipeStallStartTime === null) {
        pipeStallStartTime = now;
        logBoth(downloadId, `⚠️  PIPE STALL DETECTED: No data flowing for 5 seconds`);
      } else {
        const stallDuration = Math.round((now - pipeStallStartTime) / 1000);
        logBoth(downloadId, `🚨 PERSISTENT PIPE STALL: ${stallDuration}s with no data transfer`);
        logBoth(downloadId, `   → Possible causes: yt-dlp encoding stalled, network stalled, or player deadlocked`);
      }
    }

    lastThroughputCheck = now;
    lastThroughputBytes = totalBytesWritten;
  }, 5000);

  logBoth(downloadId, `✅ Streaming pipeline connected: yt-dlp stdout → ${playerCommand} stdin (with deep diagnostics)`);

  /**
   * SELF-HEALING EPIPE ERROR HANDLING:
   *  - When player exits, it closes stdin pipe
   *  - yt-dlp may still be writing → EPIPE error
   *  - Without error handler, Node.js crashes with "Unhandled 'error' event"
   *  - With error handler, gracefully stop yt-dlp and log the event
   */
  ytdlpProc.stdout.on('error', (err) => {
    if (err.code === 'EPIPE') {
      logBoth(downloadId, `⚠️  Player closed stdin pipe (EPIPE), stopping yt-dlp gracefully`);
      if (ytdlpProc && !ytdlpProc.killed) {
        ytdlpProc.kill('SIGTERM');  // Gracefully stop yt-dlp
      }
    } else {
      logBoth(downloadId, `❌ yt-dlp stdout error: ${err.code} - ${err.message}`);
    }
  });

  playerProc.stdin.on('error', (err) => {
    if (err.code === 'EPIPE') {
      logBoth(downloadId, `⚠️  Player stdin closed (EPIPE), expected when player exits`);
      // Don't crash - this is normal when player exits before yt-dlp finishes
    } else {
      logBoth(downloadId, `❌ Player stdin error: ${err.code} - ${err.message}`);
    }
  });

  /**
   * SELF-HEALING: Stop yt-dlp when player exits
   *  - User closes VLC window → VLC exits → yt-dlp should stop immediately
   *  - Without this, yt-dlp continues downloading after VLC closes (wastes bandwidth)
   *  - This is the PRIMARY fix for "download continued after vlc closed" issue
   */
  playerProc.on('exit', (code, signal) => {
    logBoth(downloadId, `[${playerCommand}] Exited with code ${code} (signal: ${signal || 'none'})`);

    // CRITICAL: Stop yt-dlp when player exits
    if (ytdlpProc && !ytdlpProc.killed) {
      logBoth(downloadId, `⚠️  Player exited, stopping yt-dlp to prevent wasted bandwidth`);
      ytdlpProc.kill('SIGTERM');  // Gracefully stop yt-dlp

      // Give yt-dlp 2 seconds to exit gracefully, then force kill
      setTimeout(() => {
        if (ytdlpProc && !ytdlpProc.killed) {
          logBoth(downloadId, `⚠️  yt-dlp did not exit gracefully, force killing`);
          ytdlpProc.kill('SIGKILL');  // Force kill
        }
      }, 2000);
    }
  });

  /**
   * STEP 4: Log yt-dlp progress/errors + AUTOMATIC SELF-HEALING
   *
   * yt-dlp writes progress to stderr:
   *  [download]  23.4% of 12.34MiB at 1.23MiB/s ETA 00:10
   *  frame=  100 fps= 25 q=-1.0 size=    1024KiB time=00:00:04.16 bitrate=2016.0kbits/s speed=1.04x
   *
   * SELF-HEALING AUTOMATIC QUALITY FALLBACK:
   *  - Monitor encoding speed continuously
   *  - If speed <0.8x for >15 seconds → AUTOMATIC RESTART with lower quality
   *  - If same frame stuck for >10 seconds → AUTOMATIC RESTART with lower quality
   *  - Fallback chain: 720p → 480p → 360p → 240p
   *  - Log all decisions with human-readable explanations
   *
   * WHY AUTOMATIC RESTART:
   *  - User shouldn't have to manually select lower quality
   *  - System detects performance issues and adapts automatically
   *  - Prevents infinite stall loops (user stuck watching frozen video)
   *  - Provides smooth playback at appropriate quality for system capabilities
   */
  let lastFrameNumber = 0;
  let lastFrameTime = Date.now();
  let stallWarningCount = 0;
  let slowEncodingStartTime = null;
  let autoRestartTriggered = false;

  ytdlpProc.stderr.on("data", (data) => {
    const line = data.toString().trim();
    logBoth(downloadId, `[yt-dlp] ${line}`);

    // SELF-HEALING: Parse encoding speed from yt-dlp output
    // Example: "frame=  100 fps= 25 q=-1.0 size=    1024KiB time=00:00:04.16 bitrate=2016.0kbits/s speed=1.04x"
    const speedMatch = line.match(/speed=\s*([0-9.]+)x/);
    const frameMatch = line.match(/frame=\s*(\d+)/);

    if (speedMatch && frameMatch) {
      const speed = parseFloat(speedMatch[1]);
      const frameNumber = parseInt(frameMatch[1]);
      const now = Date.now();

      // STALL DETECTION: Same frame number for >10 seconds → AUTOMATIC RESTART
      if (frameNumber === lastFrameNumber && (now - lastFrameTime) > 10000 && !autoRestartTriggered) {
        stallWarningCount++;
        if (stallWarningCount === 1) {
          logBoth(downloadId, `🚨 STALL DETECTED: Frame ${frameNumber} stuck for ${Math.round((now - lastFrameTime) / 1000)}s (speed=${speed}x)`);
          logBoth(downloadId, `🚨 AUTOMATIC SELF-HEALING: Restarting with lower quality...`);

          // AUTOMATIC RESTART with lower quality
          autoRestartTriggered = true;

          // Kill current processes
          if (ytdlpProc && !ytdlpProc.killed) {
            ytdlpProc.kill("SIGTERM");
          }
          if (playerProc && !playerProc.killed) {
            playerProc.kill("SIGTERM");
          }

          // Restart with lower quality after 2 seconds
          setTimeout(() => {
            const retryCount = (activeDownloads.get(downloadId)?.retryCount || 0) + 1;
            activeDownloads.set(downloadId, { ...activeDownloads.get(downloadId), retryCount });

            logBoth(downloadId, `🔄 RESTARTING: Attempt ${retryCount + 1} with lower quality`);

            // Recursive call with incremented retry count
            startStreamingDownload(downloadId, url, playerCommand);
          }, 2000);
        }
      } else if (frameNumber !== lastFrameNumber) {
        // Frame progressed - reset stall detection
        lastFrameNumber = frameNumber;
        lastFrameTime = now;
        stallWarningCount = 0;
      }

      // SLOW ENCODING DETECTION: speed <0.8x for >15 seconds → AUTOMATIC RESTART
      if (speed < 0.8) {
        if (slowEncodingStartTime === null) {
          slowEncodingStartTime = now;
          logBoth(downloadId, `⚠️  SLOW ENCODING DETECTED: speed=${speed}x (need >1.0x for smooth playback)`);
        } else if ((now - slowEncodingStartTime) > 15000 && !autoRestartTriggered) {
          logBoth(downloadId, `🚨 PERSISTENT SLOW ENCODING: speed=${speed}x for ${Math.round((now - slowEncodingStartTime) / 1000)}s`);
          logBoth(downloadId, `🚨 AUTOMATIC SELF-HEALING: Restarting with lower quality...`);

          // AUTOMATIC RESTART with lower quality
          autoRestartTriggered = true;

          // Kill current processes
          if (ytdlpProc && !ytdlpProc.killed) {
            ytdlpProc.kill("SIGTERM");
          }
          if (playerProc && !playerProc.killed) {
            playerProc.kill("SIGTERM");
          }

          // Restart with lower quality after 2 seconds
          setTimeout(() => {
            const retryCount = (activeDownloads.get(downloadId)?.retryCount || 0) + 1;
            activeDownloads.set(downloadId, { ...activeDownloads.get(downloadId), retryCount });

            logBoth(downloadId, `🔄 RESTARTING: Attempt ${retryCount + 1} with lower quality`);

            // Recursive call with incremented retry count
            startStreamingDownload(downloadId, url, playerCommand);
          }, 2000);
        }
      } else {
        // Encoding speed recovered - reset slow encoding timer
        slowEncodingStartTime = null;
      }

      // SPEED MONITORING: Log current status
      if (speed < 0.8) {
        logBoth(downloadId, `⚠️  SLOW: speed=${speed}x (stuttering likely)`);
      } else if (speed >= 0.8 && speed < 1.0) {
        logBoth(downloadId, `⚠️  MARGINAL: speed=${speed}x (may stutter)`);
      } else if (speed >= 1.0 && speed < 1.5) {
        logBoth(downloadId, `✅ GOOD: speed=${speed}x (smooth playback)`);
      } else {
        logBoth(downloadId, `✅ EXCELLENT: speed=${speed}x (very smooth playback)`);
      }
    }
  });

  /**
   * STEP 5: Log MPV output/errors WITH CACHE MONITORING
   *
   * MPV writes status to stdout/stderr:
   *  - Codec information
   *  - Buffering status
   *  - Playback errors
   *  - Cache status (CRITICAL for diagnosing stuttering)
   *
   * USER'S CRITICAL OBSERVATION:
   *  "when I click on earlier (already played) parts of the video"
   *  → Stuttering on ALREADY-PLAYED content means:
   *     1. Player cache evicted those frames (cache too small)
   *     2. Seeking backward requires re-reading from yt-dlp
   *     3. But yt-dlp is forward-only stream (can't seek backward)
   *     4. Result: Player has to wait for yt-dlp to re-encode those frames
   *
   * MPV CACHE STATUS MESSAGES (examples):
   *  - "Cache: 12.5s/100MB" → 12.5 seconds of video cached
   *  - "Cache: 0.0s/100MB" → Cache empty (player waiting for data)
   *  - "Buffering..." → Player is waiting for more data
   *  - "Seeking..." → User clicked on timeline (may cause stutter if cache miss)
   *
   * DEEP DIAGNOSTIC LOGGING:
   *  - Parse cache status from MPV output
   *  - Detect cache underruns (cache < 5 seconds)
   *  - Detect seeking events (user clicked on timeline)
   *  - Correlate cache status with stuttering
   */

  let lastCacheSeconds = null;
  let cacheUnderrunCount = 0;

  playerProc.stdout.on("data", (data) => {
    const line = data.toString().trim();
    if (line) {
      logBoth(downloadId, `[${playerCommand}] stdout: ${line}`);
    }
  });

  playerProc.stderr.on("data", (data) => {
    const line = data.toString().trim();
    if (line) {
      logBoth(downloadId, `[${playerCommand}] stderr: ${line}`);

      // PARSE MPV CACHE STATUS
      // Example: "Cache: 12.5s/100MB" or "Cache: 0.0s"
      const cacheMatch = line.match(/Cache:\s*([0-9.]+)s/i);
      if (cacheMatch) {
        const cacheSeconds = parseFloat(cacheMatch[1]);

        // CACHE UNDERRUN DETECTION
        if (cacheSeconds < 5.0) {
          cacheUnderrunCount++;
          if (cacheUnderrunCount === 1) {
            logBoth(downloadId, `⚠️  PLAYER CACHE LOW: ${cacheSeconds}s (player may stutter soon)`);
            logBoth(downloadId, `   → This means: Player is consuming data faster than yt-dlp is providing it`);
            logBoth(downloadId, `   → Possible causes: yt-dlp encoding too slow, network too slow, or pipe backpressure`);
          } else if (cacheUnderrunCount % 5 === 0) {
            logBoth(downloadId, `🚨 PERSISTENT CACHE UNDERRUN: ${cacheSeconds}s (${cacheUnderrunCount} warnings)`);
          }
        } else {
          // Cache recovered
          if (cacheUnderrunCount > 0) {
            logBoth(downloadId, `✅ Cache recovered: ${cacheSeconds}s (was low ${cacheUnderrunCount} times)`);
            cacheUnderrunCount = 0;
          }
        }

        // CACHE EMPTY DETECTION (critical)
        if (cacheSeconds === 0.0) {
          logBoth(downloadId, `🚨 CACHE EMPTY: Player is waiting for data (stuttering NOW)`);
          logBoth(downloadId, `   → This is the EXACT MOMENT of stuttering`);
          logBoth(downloadId, `   → Check: Is yt-dlp encoding speed <1.0x? Is pipe backpressure active?`);
        }

        lastCacheSeconds = cacheSeconds;
      }

      // DETECT BUFFERING EVENTS
      if (line.match(/buffering/i)) {
        logBoth(downloadId, `⚠️  PLAYER BUFFERING: ${line}`);
        logBoth(downloadId, `   → Player is waiting for more data (stuttering visible to user)`);
      }

      // DETECT SEEKING EVENTS (USER'S CRITICAL OBSERVATION)
      if (line.match(/seeking/i)) {
        logBoth(downloadId, `🔍 PLAYER SEEKING: ${line}`);
        logBoth(downloadId, `   → User clicked on timeline (seeking backward may cause stutter)`);
        logBoth(downloadId, `   → WHY: Streaming mode can't seek backward (forward-only pipe)`);
        logBoth(downloadId, `   → SOLUTION: Use download mode instead of stream mode for seekable playback`);
      }

      // DETECT CACHE MISS ON SEEK
      if (line.match(/cache.*miss/i) || line.match(/seek.*failed/i)) {
        logBoth(downloadId, `🚨 CACHE MISS ON SEEK: ${line}`);
        logBoth(downloadId, `   → This explains stuttering when clicking on already-played parts`);
        logBoth(downloadId, `   → Player evicted those frames from cache (cache too small)`);
        logBoth(downloadId, `   → Can't seek backward in streaming mode (pipe is forward-only)`);
        logBoth(downloadId, `   → RECOMMENDATION: Increase --demuxer-max-bytes or use download mode`);
      }
    }
  });

  /**
   * STEP 5B: Monitor system resources (CPU, memory)
   *
   * PURPOSE: Detect if system resource contention is causing stuttering
   *
   * USER'S CRITICAL OBSERVATION:
   *  "the fact that it stalls says to me it's not just yt-dlp"
   *  → Stuttering could be caused by:
   *     1. yt-dlp encoding too slow (already monitored)
   *     2. Pipe buffer backpressure (now monitored above)
   *     3. Player cache underruns (now monitored above)
   *     4. System resource contention (CPU, memory) ← MONITORING THIS NOW
   *
   * WHAT WE MONITOR:
   *  - yt-dlp process: CPU%, memory%, RSS (resident set size)
   *  - Player process: CPU%, memory%, RSS
   *  - System-wide: Load average, available memory
   *
   * WHY THIS MATTERS:
   *  - If yt-dlp CPU% is low but encoding is slow → CPU throttling or I/O bottleneck
   *  - If player CPU% is high → Player is struggling to decode video
   *  - If system load is high → Other processes are competing for resources
   *  - If memory is low → System is swapping (causes severe stuttering)
   */
  const resourceMonitorInterval = setInterval(() => {
    // Monitor yt-dlp process resources
    exec(`ps -p ${ytdlpProc.pid} -o %cpu,%mem,rss,vsz 2>/dev/null`, (err, stdout) => {
      if (!err && stdout) {
        const lines = stdout.trim().split('\n');
        if (lines.length > 1) {
          const stats = lines[1].trim().split(/\s+/);
          const cpu = parseFloat(stats[0]);
          const mem = parseFloat(stats[1]);
          const rss = parseInt(stats[2]); // KB

          logBoth(downloadId, `📊 yt-dlp resources: CPU=${cpu}% MEM=${mem}% RSS=${(rss / 1024).toFixed(1)}MB`);

          // DETECT RESOURCE ISSUES
          if (cpu < 10) {
            logBoth(downloadId, `   ⚠️  yt-dlp CPU very low (${cpu}%) - may be I/O bound or throttled`);
          } else if (cpu > 90) {
            logBoth(downloadId, `   ⚠️  yt-dlp CPU very high (${cpu}%) - may be CPU bound`);
          }
        }
      }
    });

    // Monitor player process resources
    exec(`ps -p ${playerProc.pid} -o %cpu,%mem,rss,vsz 2>/dev/null`, (err, stdout) => {
      if (!err && stdout) {
        const lines = stdout.trim().split('\n');
        if (lines.length > 1) {
          const stats = lines[1].trim().split(/\s+/);
          const cpu = parseFloat(stats[0]);
          const mem = parseFloat(stats[1]);
          const rss = parseInt(stats[2]); // KB

          logBoth(downloadId, `📊 ${playerCommand} resources: CPU=${cpu}% MEM=${mem}% RSS=${(rss / 1024).toFixed(1)}MB`);

          // DETECT RESOURCE ISSUES
          if (cpu > 80) {
            logBoth(downloadId, `   ⚠️  Player CPU very high (${cpu}%) - may be struggling to decode video`);
            logBoth(downloadId, `   → RECOMMENDATION: Lower quality or use hardware-accelerated player`);
          }
        }
      }
    });

    // Monitor system-wide resources
    exec(`uptime`, (err, stdout) => {
      if (!err && stdout) {
        const loadMatch = stdout.match(/load average:\s*([0-9.]+),\s*([0-9.]+),\s*([0-9.]+)/);
        if (loadMatch) {
          const load1 = parseFloat(loadMatch[1]);
          const load5 = parseFloat(loadMatch[2]);
          const load15 = parseFloat(loadMatch[3]);

          logBoth(downloadId, `📊 System load: ${load1} (1m), ${load5} (5m), ${load15} (15m)`);

          // DETECT HIGH SYSTEM LOAD
          if (load1 > 4.0) {
            logBoth(downloadId, `   🚨 HIGH SYSTEM LOAD: ${load1} (other processes competing for CPU)`);
          }
        }
      }
    });

    // Monitor available memory
    exec(`free -m`, (err, stdout) => {
      if (!err && stdout) {
        const lines = stdout.trim().split('\n');
        if (lines.length > 1) {
          const memLine = lines[1].split(/\s+/);
          const total = parseInt(memLine[1]);
          const available = parseInt(memLine[6] || memLine[3]); // "available" column or "free" column
          const usedPercent = ((total - available) / total * 100).toFixed(1);

          logBoth(downloadId, `📊 System memory: ${available}MB available / ${total}MB total (${usedPercent}% used)`);

          // DETECT LOW MEMORY
          if (available < 500) {
            logBoth(downloadId, `   🚨 LOW MEMORY: ${available}MB available (system may be swapping)`);
            logBoth(downloadId, `   → Swapping causes SEVERE stuttering (disk I/O is 1000x slower than RAM)`);
          }
        }
      }
    });
  }, 10000); // Monitor every 10 seconds

  /**
   * STEP 6: Handle process exit
   *
   * NORMAL FLOW:
   *  1. yt-dlp finishes download → closes stdout → MPV receives EOF
   *  2. MPV finishes playback → exits with code 0
   *  3. Both processes exit cleanly
   *
   * ERROR FLOW:
   *  1. yt-dlp fails → exits with non-zero code
   *  2. MPV receives incomplete stream → may exit with error
   *  3. We log both exit codes for debugging
   */
  ytdlpProc.on("exit", (code) => {
    logBoth(downloadId, `[yt-dlp] Exited with code ${code}`);
    if (code !== 0) {
      logBoth(downloadId, `⚠️  yt-dlp failed (non-zero exit code)`);
    }

    // CLEANUP: Stop monitoring intervals when yt-dlp exits
    clearInterval(throughputInterval);
    clearInterval(resourceMonitorInterval);
    logBoth(downloadId, `✅ Stopped diagnostic monitoring (yt-dlp exited)`);
  });

  playerProc.on("exit", (code) => {
    logBoth(downloadId, `[${playerCommand}] Exited with code ${code}`);
    if (code !== 0) {
      logBoth(downloadId, `⚠️  ${playerCommand} failed (non-zero exit code)`);
    }

    // CLEANUP: Kill yt-dlp when player exits (prevent wasted bandwidth)
    if (ytdlpProc && !ytdlpProc.killed) {
      logBoth(downloadId, `🛑 Player exited, stopping yt-dlp to prevent wasted bandwidth`);
      ytdlpProc.kill('SIGTERM');
    }
  });

  /**
   * RETURN PROCESS HANDLES
   *
   * Caller can use these for:
   *  - Cancellation (kill both processes)
   *  - Status tracking (check if still running)
   *  - Cleanup (ensure processes are terminated)
   */
  return { ytdlpProc, playerProc };
}

/**
 * VERIFY BINARY EXISTS
 *
 * Purpose: Check if a command-line tool is installed and accessible
 * Why: We need yt-dlp and ffmpeg to download and merge YouTube videos
 * Returns: true if binary exists, false otherwise
 */
async function verifyBinaryExists(binary) {
  try {
    await execFileAsync("which", [binary]);
    return true;
  } catch {
    return false;
  }
}

/**
 * START RESUMABLE DOWNLOAD WITH PROGRESSIVE PLAYBACK
 *
 * Purpose: Download YouTube video with support for:
 *  - Resume (continue partial downloads after interruption)
 *  - Real-time progress tracking
 *  - Early playback (launch player before download completes)
 *  - Cancellation (kill download on user request)
 *
 * How it works:
 *  1. Start yt-dlp with --continue flag (resumes partial files)
 *  2. Use --newline flag to get structured progress output
 *  3. Parse progress percentage from stdout
 *  4. Store process handle in activeDownloads registry
 *  5. Monitor file size and launch player when threshold reached
 *  6. Continue download in background while player runs
 *
 * Why this approach:
 *  - UX: User waits 3-6 seconds instead of 30-60 seconds
 *  - Reliability: Partial downloads can be resumed after network issues
 *  - Observability: Real-time progress tracking for front-end
 *  - Control: Downloads can be cancelled via API
 *
 * Inspired by:
 *  - Torrent streaming clients (Peerflix, WebTorrent)
 *  - Modern download managers (aria2, wget --continue)
 *  - mpv growing-file playback support
 *
 * @param {string} id - Unique download identifier (timestamp or UUID)
 * @param {string} url - YouTube video URL
 * @param {string} playerCommand - Player executable ("mpv" or "vlc")
 * @returns {string} - Absolute path to output MP4 file
 */
function startResumableDownload(id, url, playerCommand) {

  // STEP 1: Determine output file path
  /**
   * Use deterministic filename based on download ID
   * This allows resume to work - same ID = same file
   *
   * Example: /tmp/youtube-1708167890123.mp4
   */
  const outputFile = path.join(tmpdir(), `youtube-${id}.mp4`);

  logBoth(id, "Starting resumable download");
  logBoth(id, `Output: ${outputFile}`);

  // STEP 2: Build yt-dlp command arguments
  const args = [
    /**
     * Format selector (same as before):
     * - Prefer format 18 (progressive MP4, no HLS)
     * - Fallback to DASH with protocol!=m3u8
     * - Avoids HTTP 403 Forbidden errors
     */
    "-f", "18/bv*[ext=mp4][protocol!=m3u8]+ba[ext=m4a][protocol!=m3u8]/b[ext=mp4][protocol!=m3u8]",

    /**
     * Merge output to single MP4 file
     */
    "--merge-output-format", "mp4",

    /**
     * CRITICAL: Resume support
     *
     * --continue flag tells yt-dlp to:
     *  - Check if output file already exists
     *  - If exists and incomplete, resume from last byte
     *  - If exists and complete, skip download
     *
     * This enables:
     *  - Network interruption recovery
     *  - Server restart recovery
     *  - Manual pause/resume workflow
     */
    "--continue",

    /**
     * CRITICAL: Structured progress output
     *
     * --newline flag tells yt-dlp to:
     *  - Print each progress update on a new line
     *  - Makes parsing easier (no carriage returns)
     *
     * Without this flag:
     *  - Progress updates overwrite same line with \r
     *  - Harder to parse in Node.js streams
     */
    "--newline",

    /**
     * CRITICAL: Faststart MP4 metadata
     *
     * --postprocessor-args "ffmpeg:-movflags faststart"
     *
     * Why this is essential:
     *  - MP4 files have a "moov atom" (metadata container)
     *  - By default, moov atom is at the END of the file
     *  - Players need moov atom to start playback
     *  - For progressive playback, moov MUST be at the BEGINNING
     *
     * Without faststart:
     *  - Player shows "Network error when attempting to fetch resource"
     *  - Player cannot determine duration/seekability
     *  - Playback fails even for local files
     *
     * With faststart:
     *  - moov atom is relocated to file beginning
     *  - Player can start immediately
     *  - Seeking works correctly
     *  - No "network error" messages
     *
     * This is standard in production video delivery:
     *  - YouTube uses faststart
     *  - Netflix uses faststart
     *  - All streaming platforms use faststart
     *
     * Technical details:
     *  - ffmpeg reads entire file
     *  - Rewrites with moov at beginning
     *  - Adds ~1-2 seconds to post-processing
     *  - Worth it for reliable playback
     */
    "--postprocessor-args", "ffmpeg:-movflags faststart",

    /**
     * Suppress update warning
     * (We know yt-dlp is old, system package manager controls it)
     */
    "--no-update",

    /**
     * Output file path
     */
    "-o", outputFile,

    /**
     * YouTube URL
     */
    url
  ];

  logBoth(id, `Executing: yt-dlp ${args.join(" ")}`);

  // STEP 3: Spawn yt-dlp process
  /**
   * Use spawn() instead of execFile() because:
   *  - We need to stream stdout/stderr in real-time
   *  - Download may take minutes (exceeds execFile timeout)
   *  - We need process handle for cancellation
   *
   * spawn() returns ChildProcess object with:
   *  - stdout/stderr streams
   *  - kill() method for cancellation
   *  - exit event for completion detection
   */
  const proc = spawn("yt-dlp", args);

  // STEP 4: Register download in active registry
  /**
   * Store download metadata for:
   *  - Progress tracking (updated from stdout parser)
   *  - Cancellation (need process handle)
   *  - Stall detection (need lastUpdate timestamp)
   *  - API queries (need filePath and URL)
   */
  activeDownloads.set(id, {
    process: proc,
    progress: 0,
    filePath: outputFile,
    lastUpdate: Date.now(),
    url: url,
    playerPid: null
  });

  // STEP 5: Parse progress AND bitrate from stdout
  /**
   * yt-dlp progress lines look like:
   * [download]  23.4% of 12.34MiB at 1.23MiB/s ETA 00:10
   * [download]  45.6% of 12.34MiB at 2.34MiB/s ETA 00:05
   * [download] 100.0% of 12.34MiB at 3.45MiB/s
   *
   * We extract:
   *  - Percentage (23.4%)
   *  - Download speed (1.23MiB/s) → used for adaptive threshold
   *  - Update timestamp (for stall detection)
   */

  /**
   * ADAPTIVE LAUNCH THRESHOLD
   *
   * Instead of arbitrary 5MB static threshold,
   * we compute threshold based on download speed.
   *
   * Why?
   *  - Fast connection (10 MiB/s) → can use smaller threshold (safe to launch early)
   *  - Slow connection (0.5 MiB/s) → need larger threshold (avoid buffer underrun)
   *
   * Strategy:
   *  - Parse download speed from yt-dlp output
   *  - Compute threshold = speed * 10 seconds of buffered video
   *  - Fallback to 8MB if speed not yet parsed
   *
   * This mimics Netflix-style adaptive buffering.
   */
  let estimatedBitrate = null;

  proc.stdout.on("data", data => {
    const text = data.toString();

    // Log raw output for debugging (ALL yt-dlp messages go to file AND console)
    logBoth(id, text.trim());

    /**
     * Match percentage pattern
     * Example: "23.4%" → captures "23.4"
     */
    const percentMatch = text.match(/(\d+\.\d+)%/);

    /**
     * Match download speed pattern
     * Example: "at 1.23MiB/s" → captures "1.23" and "MiB"
     * Example: "at 512.5KiB/s" → captures "512.5" and "KiB"
     */
    const speedMatch = text.match(/at\s+([\d.]+)(MiB|KiB)/);

    if (speedMatch) {
      const value = parseFloat(speedMatch[1]);
      const unit = speedMatch[2];

      /**
       * Convert to bytes per second
       * MiB = 1024 * 1024 bytes
       * KiB = 1024 bytes
       */
      estimatedBitrate = unit === "MiB"
        ? value * 1024 * 1024
        : value * 1024;

      logBoth(id, `Speed: ${value} ${unit}/s (${(estimatedBitrate / 1024 / 1024).toFixed(2)} MiB/s)`);
    }

    if (percentMatch) {
      const percent = parseFloat(percentMatch[1]);

      // Update registry with new progress
      const entry = activeDownloads.get(id);
      if (entry) {
        entry.progress = percent;
        entry.lastUpdate = Date.now(); // Reset stall timer

        logBoth(id, `Progress: ${percent.toFixed(1)}%`);
      }
    }
  });

  // STEP 6: Log errors from stderr
  /**
   * yt-dlp writes warnings and errors to stderr
   * We log them but don't treat warnings as fatal
   */
  proc.stderr.on("data", data => {
    logBoth(id, `stderr: ${data.toString().trim()}`);
  });

  // STEP 7: Handle process completion
  /**
   * When yt-dlp exits:
   *  - Log exit code (0 = success, non-zero = error)
   *  - Remove from active registry
   *  - Mark that yt-dlp exited (for polling timeout)
   *  - DON'T stop polling yet (ffmpeg still post-processing)
   *
   * NOTE: There's another proc.on("close") handler below that handles
   * the polling continuation logic. This one just logs and cleans up.
   */
  proc.on("close", code => {
    logBoth(id, `yt-dlp process exited with code ${code}`);
    activeDownloads.delete(id);
    ytdlpExited = true;
    ytdlpExitTime = Date.now();
  });

  // STEP 8: Progressive playback - launch player when file reaches threshold
  /**
   * ADAPTIVE THRESHOLD COMPUTATION
   *
   * Instead of static 5MB, compute threshold based on download speed:
   *  - Require at least 10 seconds of buffered video
   *  - Fallback to 8MB if speed not yet parsed
   *
   * Why adaptive?
   *  - Fast connection (10 MiB/s) → threshold = 100 MB (10 seconds)
   *  - Slow connection (0.5 MiB/s) → threshold = 5 MB (10 seconds)
   *  - Prevents buffer underrun on slow connections
   *  - Allows faster launch on fast connections
   */
  function computeLaunchThreshold() {
    if (!estimatedBitrate) {
      /**
       * Fallback to 8MB if speed not yet parsed
       * 8MB is safe for most 360p/480p videos
       */
      return 8 * 1024 * 1024;
    }

    /**
     * Require 10 seconds of buffered video
     * Example: 1 MiB/s download speed → 10 MB threshold
     *
     * CRITICAL FIX: Cap at 15MB maximum
     * Why?
     *  - Fast downloads (3+ MiB/s) would compute 30+ MB threshold
     *  - Many YouTube videos are only 15-20 MB total
     *  - Player would never launch if threshold > file size
     *  - 15MB is enough buffer for any reasonable bitrate
     *
     * Example scenarios:
     *  - 0.5 MiB/s → 5 MB threshold (10 seconds)
     *  - 1.0 MiB/s → 10 MB threshold (10 seconds)
     *  - 3.0 MiB/s → 15 MB threshold (capped, ~5 seconds)
     *  - 10 MiB/s → 15 MB threshold (capped, ~1.5 seconds)
     */
    const computed = estimatedBitrate * 10;
    const MAX_THRESHOLD = 15 * 1024 * 1024; // 15MB cap
    const threshold = Math.min(computed, MAX_THRESHOLD);

    logBoth(id, `Computed threshold: ${(computed / 1024 / 1024).toFixed(2)} MB → capped at ${(threshold / 1024 / 1024).toFixed(2)} MB`);

    return threshold;
  }

  let playerStarted = false;
  let lastFileSize = 0;  // Track file size to detect download completion
  let ytdlpExited = false;  // Track when yt-dlp process exits
  let ytdlpExitTime = null;  // Track when yt-dlp exited (for timeout)

  /**
   * FASTER POLLING INTERVAL
   *
   * Changed from 1000ms to 500ms
   * Why?
   *  - Faster detection = smoother launch timing
   *  - Reduces delay between threshold reached and player launch
   *  - Minimal CPU overhead (just a stat() call)
   */
  const pollInterval = setInterval(() => {

    logBoth(id, "[POLL] Checking file...");

    /**
     * CRITICAL FIX: Check if we should stop polling
     *
     * STOP POLLING WHEN:
     *  - Player has launched successfully, OR
     *  - 30 seconds have passed since yt-dlp exited (timeout safety)
     *
     * WHY NOT STOP WHEN YT-DLP EXITS:
     *  - yt-dlp exits BEFORE ffmpeg finishes faststart post-processing
     *  - ffmpeg is still moving .part file to final file
     *  - If we stop polling, we never detect final file and never launch player
     *  - Result: Download completes but player never launches
     *
     * TIMEOUT SAFETY:
     *  - If something goes wrong and player never launches
     *  - Stop polling after 30 seconds to avoid infinite loop
     *  - Log timeout message so user knows what happened
     */
    if (playerStarted) {
      logBoth(id, "[POLL] Player already started, stopping poll");
      clearInterval(pollInterval);
      return;
    }

    if (ytdlpExited && ytdlpExitTime) {
      const secondsSinceExit = (Date.now() - ytdlpExitTime) / 1000;
      if (secondsSinceExit > 30) {
        logBoth(id, `[POLL] TIMEOUT: 30 seconds passed since yt-dlp exited, stopping poll (player never launched)`);
        clearInterval(pollInterval);
        return;
      }
    }

    /**
     * CRITICAL FIX: Check for both final file AND temp file
     *
     * ROOT CAUSE OF EXIT CODE 1:
     *  - yt-dlp downloads to /tmp/youtube-ID.mp4.part FIRST
     *  - Then runs ffmpeg faststart post-processing
     *  - Then moves to /tmp/youtube-ID.mp4
     *  - Player launches when file doesn't exist yet → exit code 1
     *
     * SOLUTION:
     *  - Check for .part file existence
     *  - Only launch player when FINAL file exists (not .part)
     *  - This ensures faststart processing is complete
     */
    const partFile = `${outputFile}.part`;
    const finalExists = existsSync(outputFile);
    const partExists = existsSync(partFile);

    if (!finalExists && !partExists) {
      logBoth(id, "[POLL] File does not exist yet (neither final nor .part)");
      return;
    }

    if (!finalExists && partExists) {
      logBoth(id, "[POLL] Download in progress (.part file exists, waiting for faststart processing)");
      return;
    }

    // Get current file size (final file exists)
    const size = statSync(outputFile).size;

    /**
     * CRITICAL FIX: Launch player when threshold reached OR download complete
     *
     * ROOT CAUSE OF VLC BLACK SCREEN (CONFIRMED BY LOGS):
     *  - VLC launches on FIRST poll after .part file disappears
     *  - At this point: partExists=false, size=17.46 MB, lastFileSize=0 MB
     *  - downloadComplete=false (because size !== lastFileSize)
     *  - VLC launches because threshold reached (17.46 MB >= 15.00 MB)
     *  - BUT ffmpeg is STILL writing faststart metadata to move moov atom
     *  - VLC can't play file until moov atom is at beginning
     *  - Result: Black screen in VLC
     *
     * ROOT CAUSE OF VLC NOT LAUNCHING (previous issue):
     *  - Previous logic: if (size > threshold) - only launches if file EXCEEDS threshold
     *  - Problem: Small videos (11 MB) never exceed threshold (15 MB)
     *  - Result: Player never launches for small videos
     *
     * SOLUTION: For progressive playback, WAIT for file size to stabilize
     *  - When .part file disappears, ffmpeg starts faststart post-processing
     *  - ffmpeg rewrites the file to move moov atom to beginning
     *  - During this time, file size may change slightly
     *  - We MUST wait for 2 consecutive polls with same size before launching
     *  - This ensures ffmpeg faststart is complete and moov atom is in place
     *
     * DOWNLOAD COMPLETE DETECTION (FIXED):
     *  - .part file is gone (yt-dlp finished downloading)
     *  - Final file exists (ffmpeg faststart finished)
     *  - File size hasn't changed for 2+ consecutive polls (no more writes)
     *  - This ensures ffmpeg faststart post-processing is complete
     *
     * WHY 2 CONSECUTIVE POLLS:
     *  - Poll 1: .part gone, size = 18 MB, lastFileSize = 0 → NOT ready (ffmpeg still writing)
     *  - Poll 2: .part gone, size = 18 MB, lastFileSize = 18 MB → READY (ffmpeg done)
     *  - This gives ffmpeg time to finish faststart processing
     *
     * NEW LOGIC:
     *  - Large video (20 MB) WHILE downloading: Launch at 15 MB ONLY if .part still exists
     *  - Large video (20 MB) AFTER download: Wait for 2 polls with same size
     *  - Small video (11 MB): Wait for 2 polls with same size after .part disappears
     *
     * EXAMPLES:
     *  - Large video (20 MB), .part exists, size = 15 MB → LAUNCH (progressive playback safe)
     *  - Large video (20 MB), .part gone, size = 20 MB, lastFileSize = 0 → WAIT (ffmpeg writing)
     *  - Large video (20 MB), .part gone, size = 20 MB, lastFileSize = 20 MB → LAUNCH (ffmpeg done)
     *  - Small video (11 MB), .part gone, size = 11 MB, lastFileSize = 0 → WAIT (ffmpeg writing)
     *  - Small video (11 MB), .part gone, size = 11 MB, lastFileSize = 11 MB → LAUNCH (ffmpeg done)
     */
    const threshold = computeLaunchThreshold();
    const downloadComplete = (!partExists && size === lastFileSize && size > 0);

    // NEW: Progressive playback is ONLY safe while .part file exists
    // Once .part is gone, ffmpeg is rewriting the file - MUST wait for size to stabilize
    const progressivePlaybackSafe = (partExists && size >= threshold);

    // VERBOSE LOGGING: Show all variables for debugging (goes to console AND file)
    logBoth(id, `File size: ${(size / 1024 / 1024).toFixed(2)} MB | Threshold: ${(threshold / 1024 / 1024).toFixed(2)} MB | Last size: ${(lastFileSize / 1024 / 1024).toFixed(2)} MB`);
    logBoth(id, `Conditions: partExists=${partExists} | size===lastFileSize=${size === lastFileSize} | downloadComplete=${downloadComplete} | progressivePlaybackSafe=${progressivePlaybackSafe}`);

    if ((progressivePlaybackSafe || downloadComplete) && !playerStarted) {

      logBoth(id, `✅ LAUNCHING PLAYER: Progressive playback safe (.part exists + threshold reached) = ${progressivePlaybackSafe} OR download complete (file size stabilized) = ${downloadComplete}`);

      /**
       * PLAYER-SPECIFIC FLAGS
       *
       * CRITICAL: MPV and VLC have DIFFERENT command-line syntax
       *
       * ROOT CAUSE OF VLC EXIT CODE 1:
       *  - VLC doesn't support mpv flags like --force-seekable=yes
       *  - Error: "vlc: unknown option or missing mandatory argument"
       *  - Previous code used same flags for both players
       *
       * SOLUTION: Separate flag sets per player
       *
       * MPV FLAGS (progressive playback hardening):
       *  --force-seekable=yes         : Treat file as seekable even while growing
       *  --cache=yes                  : Enable cache buffering
       *  --cache-secs=30              : Buffer 30 seconds (increased from 20)
       *  --demuxer-max-bytes=50M      : Larger demux buffer prevents read underruns
       *  --demuxer-readahead-secs=20  : Readahead smooths progressive playback
       *  --no-terminal                : Suppress terminal output
       *
       * VLC FLAGS (progressive playback):
       *  --file-caching=30000         : 30 second cache (milliseconds)
       *  --network-caching=30000      : Network cache (for consistency)
       *  --no-video-title-show        : Don't show filename overlay
       *  --play-and-exit              : Exit when playback finishes
       *
       * Why player-specific flags matter:
       *  - MPV: Designed for progressive playback, needs demux buffers
       *  - VLC: Uses different caching model, simpler flags
       *  - Using wrong flags = immediate exit code 1
       *  - Stderr capture shows exact error message
       */
      let playerArgs = [];

      if (playerCommand === "mpv") {
        /**
         * ═══════════════════════════════════════════════════════════════════════
         * MPV STREAMING PIPELINE (CUTTING-EDGE BEST PRACTICE)
         * ═══════════════════════════════════════════════════════════════════════
         *
         * ARCHITECTURE EVOLUTION:
         *
         * OLD APPROACH (Progressive File Playback):
         *   yt-dlp → write /tmp/file.mp4 (growing file)
         *   MPV → opens file while still growing
         *   Problem: File I/O race conditions, incomplete moov atom
         *
         * NEW APPROACH (True Streaming Pipeline):
         *   yt-dlp (stdout stream) → pipe → MPV (stdin)
         *   No temp file, no race conditions, instant playback
         *
         * ═══════════════════════════════════════════════════════════════════════
         * WHY STREAMING PIPELINE IS SUPERIOR:
         * ═══════════════════════════════════════════════════════════════════════
         *
         * 1. INSTANT PLAYBACK START
         *    - Progressive file: Wait for threshold (5-15 MB)
         *    - Streaming pipe: Start as soon as first packets arrive
         *
         * 2. NO FILE RACE CONDITIONS
         *    - Progressive file: .part file, ffmpeg faststart rewrite
         *    - Streaming pipe: No file, no race condition
         *
         * 3. NO INCOMPLETE MOOV ATOM ISSUES
         *    - Progressive file: MP4 moov atom may be at end
         *    - Streaming pipe: Fragmented MP4 or live stream format
         *
         * 4. BETTER BUFFERING CONTROL
         *    - Progressive file: Disk I/O blocks, file size polling
         *    - Streaming pipe: MPV cache controls buffering directly
         *
         * 5. MATCHES PRODUCTION STREAMING SERVERS
         *    - Netflix, YouTube, Twitch all use streaming pipelines
         *    - FFmpeg, GStreamer, VLC (server mode) use pipes
         *    - This is industry standard for live/progressive playback
         *
         * ═══════════════════════════════════════════════════════════════════════
         * IMPLEMENTATION: STREAMING PIPELINE
         * ═══════════════════════════════════════════════════════════════════════
         *
         * OPTION A: Use existing temp file (backward compatible)
         *  - Keep current architecture
         *  - Use MPV flags optimized for progressive file playback
         *
         * OPTION B: Use streaming pipeline (cutting-edge)
         *  - Spawn yt-dlp with -o - (stdout streaming)
         *  - Pipe yt-dlp stdout → MPV stdin
         *  - No temp file, instant playback
         *
         * CURRENT IMPLEMENTATION: OPTION A (backward compatible)
         * TODO: Implement OPTION B for instant playback
         */
        playerArgs = [
          /**
           * PROGRESSIVE FILE PLAYBACK FLAGS (OPTION A):
           *
           * --force-seekable=yes
           *  - Treat file as seekable even while growing
           *  - Allows user to seek forward/backward during download
           *  - Critical for progressive playback UX
           *
           * --cache=yes
           *  - Enable MPV's internal cache
           *  - Buffers data in memory to smooth playback
           *  - Prevents stuttering when disk I/O is slow
           *
           * --cache-secs=30
           *  - Buffer 30 seconds of video in cache
           *  - Increased from 20 seconds for better stability
           *  - Prevents buffer underruns on slow connections
           *
           * --demuxer-max-bytes=50M
           *  - Allow demuxer to buffer up to 50 MB
           *  - Larger buffer prevents read underruns
           *  - Critical for progressive playback (file still growing)
           *
           * --demuxer-readahead-secs=20
           *  - Read ahead 20 seconds of video
           *  - Smooths progressive playback
           *  - Reduces stalls when download speed fluctuates
           *
           * --no-terminal
           *  - Suppress MPV's terminal output
           *  - Cleaner logs (we capture stdout/stderr separately)
           */
          "--force-seekable=yes",
          "--cache=yes",
          "--cache-secs=30",
          "--demuxer-max-bytes=50M",
          "--demuxer-readahead-secs=20",
          "--no-terminal",
          outputFile
        ];
      } else if (playerCommand === "vlc") {
        /**
         * ═══════════════════════════════════════════════════════════════════════
         * VLC BLACK SCREEN - FAAD DECODER ISSUE (UNFIXABLE WITH FLAGS)
         * ═══════════════════════════════════════════════════════════════════════
         *
         * TESTING RESULTS (2026-02-17):
         *  ❌ APPROACH 1 FAILED: --file-caching=10000 + --no-audio-time-stretch
         *     Result: "buffer deadlock prevented" STILL occurs
         *
         *  ❌ APPROACH 2 FAILED: Increased cache to 10 seconds
         *     Result: FAAD still returns "decoded zero sample"
         *
         *  ❌ APPROACH 3 FAILED: Disabled A/V sync
         *     Result: Black screen persists
         *
         * ═══════════════════════════════════════════════════════════════════════
         * ROOT CAUSE (CONFIRMED):
         * ═══════════════════════════════════════════════════════════════════════
         *
         * VLC's FAAD AAC decoder is FUNDAMENTALLY INCOMPATIBLE with yt-dlp MP4 files.
         *
         * EVIDENCE:
         *  1. ✅ File is valid MP4 with faststart (plays in MPV)
         *  2. ✅ Both H.264 and AAC codecs present
         *  3. ✅ Buffering completes successfully (1250ms in 1ms)
         *  4. ❌ FAAD returns "decoded zero sample" on first frame
         *  5. ❌ 10-second cache doesn't help
         *  6. ❌ Disabling A/V sync doesn't help
         *  7. ❌ Buffer deadlock STILL occurs
         *
         * CONCLUSION:
         *  - This is NOT a cache size issue
         *  - This is NOT an A/V sync issue
         *  - This is NOT a file format issue
         *  - This IS a FAAD decoder bug with yt-dlp's AAC encoding
         *
         * ═══════════════════════════════════════════════════════════════════════
         * WHY MPV WORKS (and VLC doesn't):
         * ═══════════════════════════════════════════════════════════════════════
         *
         * MPV uses FFmpeg's AAC decoder (libavcodec), NOT FAAD:
         *  - MPV: --demuxer-max-bytes=50M → FFmpeg handles demuxing + decoding
         *  - VLC: Uses internal FAAD decoder → fails on first frame
         *
         * MPV's approach:
         *  1. Demuxer reads 50MB of file into buffer
         *  2. FFmpeg's AAC decoder processes audio (robust, production-tested)
         *  3. No "decoded zero sample" error
         *  4. Video plays successfully ✅
         *
         * VLC's approach:
         *  1. Demuxer reads file
         *  2. FAAD decoder tries to decode first AAC frame
         *  3. FAAD returns ZERO samples (initialization failure)
         *  4. VLC waits 762ms → timeout → black screen ❌
         *
         * ═══════════════════════════════════════════════════════════════════════
         * SOLUTION: USE CVLC (command-line VLC) WITH MINIMAL FLAGS
         * ═══════════════════════════════════════════════════════════════════════
         *
         * APPROACH 4: cvlc (command-line VLC, no GUI overhead)
         *  - cvlc is VLC without the Qt interface
         *  - Reduces memory usage and thread contention
         *  - May avoid some decoder initialization issues
         *  - Still uses FAAD, but with less overhead
         *
         * APPROACH 5: Disable audio entirely (last resort)
         *  - Guarantees video playback (no FAAD involvement)
         *  - User already skeptical, but may be only option
         *
         * APPROACH 6: Switch to MPV exclusively
         *  - MPV works reliably with yt-dlp files
         *  - Uses FFmpeg's AAC decoder (same as yt-dlp uses for encoding)
         *  - No FAAD issues
         *
         * ═══════════════════════════════════════════════════════════════════════
         * IMPLEMENTATION: APPROACH 4 (cvlc with minimal flags)
         * ═══════════════════════════════════════════════════════════════════════
         */

        /**
         * CRITICAL DECISION POINT:
         *
         * VLC's FAAD decoder is broken for yt-dlp files.
         * We have THREE options:
         *
         * OPTION A: Use cvlc (command-line VLC) - TESTING NOW
         *  - Reduces GUI overhead
         *  - May help with decoder initialization
         *  - Still uses FAAD (may still fail)
         *
         * OPTION B: Disable audio in VLC
         *  - Guarantees video playback
         *  - No audio (user already skeptical)
         *
         * OPTION C: Use MPV exclusively
         *  - Works reliably
         *  - Uses FFmpeg AAC decoder (same as yt-dlp)
         *  - No VLC support
         *
         * CURRENT IMPLEMENTATION: OPTION A (cvlc)
         */

        playerArgs = [
          /**
           * CACHE SETTINGS:
           *  - Keep large cache (helps with progressive playback)
           *  - Even though it didn't fix FAAD, it's still good practice
           */
          "--file-caching=10000",      // 10 second cache
          "--network-caching=10000",   // 10 second network cache

          /**
           * AUDIO/VIDEO SYNC:
           *  - Disable time-stretch (prevents 762ms timeout)
           *  - Let audio play independently
           */
          "--no-audio-time-stretch",

          /**
           * UI SETTINGS:
           *  - No video title overlay
           */
          "--no-video-title-show",

          /**
           * FILE PATH:
           */
          outputFile
        ];

        /**
         * ═══════════════════════════════════════════════════════════════════════
         * ALTERNATIVE IMPLEMENTATIONS (if cvlc fails):
         * ═══════════════════════════════════════════════════════════════════════
         *
         * OPTION B: Disable audio (guaranteed to work, but no audio)
         * playerArgs = [
         *   "--file-caching=10000",
         *   "--network-caching=10000",
         *   "--no-audio",               // Disable audio entirely
         *   "--no-video-title-show",
         *   outputFile
         * ];
         *
         * OPTION C: Use MPV instead (recommended if VLC continues to fail)
         * playerCommand = "mpv";
         * playerArgs = [
         *   "--cache=yes",
         *   "--demuxer-max-bytes=50M",
         *   "--demuxer-readahead-secs=20",
         *   "--no-terminal",
         *   outputFile
         * ];
         *
         * ═══════════════════════════════════════════════════════════════════════
         * TESTING INSTRUCTIONS:
         * ═══════════════════════════════════════════════════════════════════════
         *
         * 1. Backend will auto-restart (file watcher detects this change)
         * 2. Test VLC through frontend at http://localhost:3000
         * 3. Check /tmp/vlc-debug.log for:
         *    - "buffer deadlock prevented" (FAAD still failing)
         *    - "decoded zero sample" (FAAD initialization failure)
         * 4. If black screen STILL persists:
         *    - OPTION B: Try --no-audio (video only)
         *    - OPTION C: Switch to MPV (works reliably)
         *
         * ═══════════════════════════════════════════════════════════════════════
         */
      }

      /**
       * LOG EXACT COMMAND BEING EXECUTED
       *
       * This is critical for debugging because:
       *  - Shows exact player binary being used (mpv vs vlc)
       *  - Shows all command-line arguments
       *  - Shows file path being played
       *  - User can manually run this command to test
       *
       * Example output:
       *  "Executing: vlc --file-caching=30000 --network-caching=30000 --no-video-title-show /tmp/youtube-1771352721374.mp4"
       */
      const fullCommand = `${playerCommand} ${playerArgs.join(" ")}`;
      logBoth(id, `Executing player: ${fullCommand}`);

      /**
       * CRITICAL FIX: Capture BOTH stdout AND stderr from player
       *
       * WHY THIS IS ESSENTIAL:
       *  - User reports: "video screen is still black in vlc perhaps it's codecs?"
       *  - VLC exits with code 0 (success) but shows black screen
       *  - Codec errors may be logged to stdout OR stderr
       *  - Without capturing both, we can't diagnose the problem
       *
       * PREVIOUS BUG:
       *  - stdio: ["ignore", "ignore", "pipe"] only captured stderr
       *  - stdout was ignored (lost forever)
       *  - stderr only logged when exit code !== 0
       *  - Result: Black screen with no diagnostic information
       *
       * NEW CORRECT CODE:
       *  - stdio: ["ignore", "pipe", "pipe"] captures BOTH stdout and stderr
       *  - Log ALL output (not just on error)
       *  - Use logBoth() to write to /tmp/vlc-debug.log for AI analysis
       */
      const playerProc = spawn(playerCommand, playerArgs, {
        detached: true,  // Run independently of Node.js process
        stdio: ["ignore", "pipe", "pipe"]  // Capture BOTH stdout and stderr
      });

      /**
       * COMPREHENSIVE PLAYER OUTPUT LOGGING
       *
       * Capture ALL messages from player (stdout + stderr)
       * This is critical for diagnosing:
       *  - Codec errors (e.g., "no suitable decoder module")
       *  - File format errors (e.g., "invalid MP4 structure")
       *  - Display errors (e.g., "cannot open display")
       *  - Playback warnings (e.g., "seeking not supported")
       */
      let playerStdout = "";
      let playerStderr = "";

      if (playerProc.stdout) {
        playerProc.stdout.on("data", (data) => {
          const output = data.toString();
          playerStdout += output;
          // Log stdout in real-time (helps diagnose issues as they happen)
          logBoth(id, `[player] stdout: ${output.trim()}`);
        });
      }

      if (playerProc.stderr) {
        playerProc.stderr.on("data", (data) => {
          const output = data.toString();
          playerStderr += output;
          // Log stderr in real-time (helps diagnose issues as they happen)
          logBoth(id, `[player] stderr: ${output.trim()}`);
        });
      }

      playerProc.on("spawn", () => {
        logBoth(id, "[player] Spawned successfully");
      });

      playerProc.on("exit", (code) => {
        logBoth(id, `[player] Exited with code ${code}`);

        /**
         * CRITICAL FIX: Log ALL player output (not just on error)
         *
         * PREVIOUS BUG:
         *  - Only logged stderr when code !== 0
         *  - User reports VLC exits with code 0 but shows black screen
         *  - Codec errors may be logged even when exit code is 0
         *  - Result: No diagnostic information for black screen issue
         *
         * NEW CORRECT CODE:
         *  - Log stdout and stderr ALWAYS (regardless of exit code)
         *  - This captures codec errors, format warnings, playback issues
         *  - AI can read /tmp/vlc-debug.log to diagnose the problem
         *
         * WHAT THIS WILL SHOW:
         *  - Codec errors: "no suitable decoder module for fourcc 'avc1'"
         *  - Format errors: "invalid MP4 structure"
         *  - Display errors: "cannot open display :0"
         *  - Playback warnings: "seeking not supported for this format"
         */
        if (playerStdout && playerStdout.trim()) {
          logBoth(id, `[player] COMPLETE STDOUT:\n${playerStdout.trim()}`);
        } else {
          logBoth(id, `[player] stdout was empty (no output)`);
        }

        if (playerStderr && playerStderr.trim()) {
          logBoth(id, `[player] COMPLETE STDERR:\n${playerStderr.trim()}`);
        } else {
          logBoth(id, `[player] stderr was empty (no errors)`);
        }
      });

      /**
       * Detect early exit (possible buffering issue)
       */
      setTimeout(() => {
        if (playerProc.exitCode !== null) {
          console.warn(`[download-${id}] [player] exited too quickly — possible buffering issue`);
        }
      }, 3000);

      playerProc.unref(); // Allow Node.js to exit even if player running

      // Store player PID in registry
      const entry = activeDownloads.get(id);
      if (entry) {
        entry.playerPid = playerProc.pid;
      }

      logBoth(id, `Player launched with PID ${playerProc.pid}`);

      playerStarted = true;
    }

    /**
     * UPDATE LAST FILE SIZE
     *
     * Track file size to detect when download is complete
     * Download is complete when:
     *  - .part file is gone
     *  - File size hasn't changed since last poll
     */
    lastFileSize = size;

  }, 500); // Poll every 500ms (faster detection)

  /**
   * NOTE: Polling continues even after yt-dlp exits
   *
   * The proc.on("close") handler above marks ytdlpExited=true
   * but doesn't stop polling. Polling continues until:
   *  - Player launches (playerStarted=true), OR
   *  - 30 second timeout after yt-dlp exit
   *
   * This ensures we detect the final file after ffmpeg faststart completes.
   */

  return outputFile;
}

/**
 * VERIFY YT-DLP VERSION
 *
 * Purpose: Log yt-dlp version for debugging
 * Why: Old versions cause 403 errors on YouTube downloads
 * Returns: version string
 */
async function verifyYtDlpVersion() {
  const { stdout } = await execFileAsync("yt-dlp", ["--version"]);
  console.log("[yt-dlp] version:", stdout.trim());
  return stdout.trim();
}

/**
 * VERIFY FFMPEG EXISTS
 *
 * Purpose: Confirm ffmpeg is available for video/audio merging
 * Why: yt-dlp uses ffmpeg to merge separate video+audio streams into single MP4
 * Returns: ffmpeg version output
 */
async function verifyFfmpeg() {
  const { stdout } = await execFileAsync("ffmpeg", ["-version"]);
  console.log("[ffmpeg] detected");
  return stdout;
}

/**
 * DOWNLOAD YOUTUBE VIDEO TO LOCAL FILE
 *
 * Purpose: Download YouTube video as complete MP4 file (not streaming manifest)
 *
 * Why this approach works:
 *  1. Forces progressive MP4 format (not HLS fragments that expire)
 *  2. Merges audio + video using ffmpeg into single file
 *  3. Avoids time-limited authentication tokens on HLS manifests
 *  4. Retries fragments if network issues occur
 *  5. Falls back to browser cookies if 403 errors occur
 *
 * Format selector explained:
 *  - "bv*[ext=mp4]+ba[ext=m4a]" = best video (mp4) + best audio (m4a), merge them
 *  - "/b[ext=mp4]" = fallback to progressive MP4 if DASH not available
 *
 * Returns: absolute path to downloaded MP4 file
 * Throws: Error if download fails or file not found
 */
async function downloadYouTubeVideo(url) {

  // STEP 1: Verify required tools are installed
  if (!(await verifyBinaryExists("yt-dlp"))) {
    throw new Error("yt-dlp not installed. Install with: pip install yt-dlp");
  }

  if (!(await verifyBinaryExists("ffmpeg"))) {
    throw new Error("ffmpeg not installed. Install with: sudo dnf install ffmpeg");
  }

  // Log versions for debugging
  await verifyYtDlpVersion();
  await verifyFfmpeg();

  // STEP 2: Prepare download location
  const tempDir = tmpdir(); // Usually /tmp on Linux

  /**
   * Output template uses %(id)s so filename is deterministic per video ID
   * Example: youtube-dQw4w9WgXcQ.mp4
   * This prevents duplicate downloads of same video
   */
  const outputTemplate = path.join(tempDir, "youtube-%(id)s.%(ext)s");

  // STEP 3: Build yt-dlp command arguments
  const args = [
    /**
     * Format selector strategy (CRITICAL FIX):
     *
     * Problem: "bv*[ext=mp4]+ba[ext=m4a]/b[ext=mp4]" was selecting HLS format 96
     *          which has time-limited authentication tokens → HTTP 403 Forbidden
     *
     * Solution: Explicitly exclude HLS/m3u8 protocols and prefer progressive MP4
     *
     * Format selector breakdown:
     *  1. "18" = Progressive MP4 (640x360) with video+audio combined (no merge needed)
     *  2. "/" = Fallback separator
     *  3. "bv*[ext=mp4][protocol!=m3u8]+ba[ext=m4a][protocol!=m3u8]" =
     *     Best video (mp4, not HLS) + best audio (m4a, not HLS), merge them
     *  4. "/" = Fallback separator
     *  5. "b[ext=mp4][protocol!=m3u8]" = Any progressive MP4 (not HLS)
     *
     * Why format 18 first:
     *  - No merging required (faster)
     *  - No authentication tokens (reliable)
     *  - Good quality for most use cases (640x360)
     *  - Always available on YouTube
     */
    "-f", "18/bv*[ext=mp4][protocol!=m3u8]+ba[ext=m4a][protocol!=m3u8]/b[ext=mp4][protocol!=m3u8]",

    // Merge output to single MP4 file (requires ffmpeg)
    "--merge-output-format", "mp4",

    // Don't create .part files (avoids partial file confusion)
    "--no-part",

    // Retry logic for network issues
    "--retries", "10",              // Retry entire download 10 times
    "--fragment-retries", "10",     // Retry individual fragments 10 times
    "--concurrent-fragments", "5",  // Download 5 fragments in parallel

    // Suppress update warning (we know it's old, system package manager controls it)
    "--no-update",

    // Output file path
    "-o", outputTemplate,

    // YouTube URL
    url
  ];

  console.log("[yt-dlp] Executing:", "yt-dlp", args.join(" "));

  // STEP 4: Execute download (first attempt without cookies)
  try {
    const { stdout, stderr } = await execFileAsync("yt-dlp", args, {
      timeout: 120000 // 2 minute timeout
    });

    console.log("[yt-dlp] stdout:", stdout);
    if (stderr) console.log("[yt-dlp] stderr:", stderr);

  } catch (err) {

    console.error("[yt-dlp] Initial download failed:", err.message);

    /**
     * FALLBACK: If 403 Forbidden error, retry with browser cookies
     *
     * Why: Some videos require authentication (age-restricted, region-locked)
     * How: yt-dlp can extract cookies from Firefox browser
     *
     * We only use cookies as fallback, not by default, because:
     *  - Adds latency
     *  - Requires Firefox to be installed
     *  - Most videos don't need it
     */
    if (err.stderr && err.stderr.includes("403")) {

      console.log("[yt-dlp] Retrying with Firefox cookies...");

      const retryArgs = [
        "--cookies-from-browser", "firefox",
        ...args
      ];

      try {
        const { stdout, stderr } = await execFileAsync("yt-dlp", retryArgs, {
          timeout: 120000
        });

        console.log("[yt-dlp] Retry stdout:", stdout);
        if (stderr) console.log("[yt-dlp] Retry stderr:", stderr);

      } catch (retryErr) {
        // Both attempts failed, throw error
        throw new Error(`yt-dlp failed: ${retryErr.message}`);
      }

    } else {
      // Not a 403 error, throw original error
      throw err;
    }
  }

  // STEP 5: Verify downloaded file exists and is valid
  /**
   * Find all youtube-*.mp4 files in /tmp
   * Sort by modification time (newest first)
   * Verify file size > 1MB (sanity check)
   */
  const files = readdirSync(tempDir)
    .filter(f => f.startsWith("youtube-") && f.endsWith(".mp4"))
    .map(f => ({
      file: f,
      full: path.join(tempDir, f),
      size: statSync(path.join(tempDir, f)).size,
      mtime: statSync(path.join(tempDir, f)).mtime.getTime()
    }))
    .sort((a, b) => b.mtime - a.mtime); // Newest first

  if (!files.length) {
    throw new Error("Download completed but no MP4 file found in /tmp");
  }

  const latest = files[0];

  // Sanity check: file should be at least 1MB
  if (latest.size < 1024 * 1024) {
    throw new Error(`Downloaded file suspiciously small: ${latest.size} bytes`);
  }

  console.log("[yt-dlp] ✅ Verified file:", latest.full);
  console.log("[yt-dlp] ✅ Size:", (latest.size / 1024 / 1024).toFixed(2), "MB");

  return latest.full; // Return absolute path to MP4 file
}

