/**
 * SELF-HEALING: Auto-restart on code changes
 *
 * WHY THIS IS CRITICAL:
 *  - User (or AI) edits server.js to fix bugs
 *  - Backend keeps running OLD code from memory
 *  - User tests and sees OLD behavior (bug still present)
 *  - User thinks fix didn't work
 *  - User wastes time debugging
 *  - User has to manually kill and restart backend
 *
 * ROOT CAUSE:
 *  - Node.js loads server.js into memory at startup
 *  - Editing the file on disk doesn't affect running process
 *  - Process must be restarted to load new code
 *  - Manual restart = friction = bad UX
 *
 * SOLUTION: Watch server.js for changes and auto-restart
 *  - When server.js changes on disk, kill current process
 *  - Process manager (npm, systemd, forever, pm2) will restart it
 *  - New process loads NEW code from disk
 *  - User sees NEW behavior immediately
 *  - Zero manual intervention required
 *
 * IMPLEMENTATION:
 *  - Use fs.watch() to monitor server.js file (ES module import)
 *  - On "change" event, log message and exit cleanly
 *  - Exit code 0 = clean shutdown (not a crash)
 *  - Process manager sees exit and restarts automatically
 *  - __filename in ES modules = import.meta.url converted to path
 *
 * ALTERNATIVE: Use nodemon in development
 *  - npm install -g nodemon
 *  - nodemon server.js
 *  - Auto-restarts on any .js file change
 *  - More features (delay, ignore patterns, etc.)
 *
 * PRODUCTION: Use pm2 or systemd with auto-restart
 *  - pm2 start server.js --watch
 *  - systemd Restart=always
 */
import { watch } from "fs";
import { fileURLToPath } from "url";

// ES module equivalent of __filename
const __filename = fileURLToPath(import.meta.url);

watch(__filename, (eventType, filename) => {
  if (eventType === "change") {
    console.log(`[SELF-HEAL] server.js changed on disk, restarting to load new code...`);
    console.log(`[SELF-HEAL] Process will exit cleanly and be restarted by process manager`);
    process.exit(0);  // Clean exit, process manager will restart
  }
});

