/**
 * 🔥 CRITICAL MEMORY LEAK FIX (2026-02-18):
 *  - Clear all intervals on server shutdown
 *  - Kill all active download processes
 *  - Remove all event listeners
 *  - Without cleanup, intervals run FOREVER accumulating memory
 *  - This was causing 1409GB virtual memory usage in VS Code extension
 *
 * ROOT CAUSE:
 *  - stallDetectorInterval runs every 10 seconds FOREVER
 *  - Each iteration creates closures over activeDownloads Map
 *  - VS Code extension keeps process alive even after server "exits"
 *  - Memory accumulates: 10s → 1min → 1hr → 1409GB virtual memory
 *
 * FIX:
 *  - Clear stallDetectorInterval on SIGTERM/SIGINT
 *  - Kill all active download processes
 *  - Exit cleanly with code 0
 */
process.on('SIGTERM', () => {
  console.log('[CLEANUP] SIGTERM received, cleaning up resources...');

  // Clear global stall detector interval
  clearInterval(stallDetectorInterval);
  console.log('[CLEANUP] Cleared stallDetectorInterval');

  // Kill all active downloads
  for (const [id, entry] of activeDownloads.entries()) {
    if (entry.process && !entry.process.killed) {
      console.log(`[CLEANUP] Killing download ${id} (PID ${entry.process.pid})`);
      entry.process.kill('SIGTERM');
    }
  }

  // Clear activeDownloads registry
  activeDownloads.clear();
  console.log('[CLEANUP] Cleared activeDownloads registry');

  console.log('[CLEANUP] Shutdown complete, exiting...');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('[CLEANUP] SIGINT received (Ctrl+C), cleaning up resources...');

  // Clear global stall detector interval
