import { useState, useEffect } from "react";
import "./AutoFix.css";

export default function AutoFix({ preferences, categories, showToast, onFixed }) {
  const [fixing, setFixing] = useState(false);
  const [result, setResult] = useState(null);
  const [externalPlayers, setExternalPlayers] = useState(null);
  const [loadingPlayers, setLoadingPlayers] = useState(false);
  const [videoUrl, setVideoUrl] = useState("");
  const [playingVideo, setPlayingVideo] = useState(false);

const [quality, setQuality] = useState("auto"); // auto, 360p, 480p, 720p, 1080p
const [downloadMode, setDownloadMode] = useState("stream"); // stream, download
const [downloadProgress, setDownloadProgress] = useState(null);

// Calculate issue count
const flatPrefs = {};
for (const cat of Object.values(categories || {})) {
  for (const [key, val] of Object.entries(cat)) {
    flatPrefs[key] = val.expected;
  }
}

const issueCount = Object.keys(flatPrefs).filter(
  (k) => preferences[k] !== flatPrefs[k],
).length;

const handleAutoFix = async () => {
  if (fixing) return;

  const confirmed = window.confirm(
    `Auto-fix will:\n\n` +
    `✅ Close Firefox (this page will close too!)\n` +
    `✅ Fix ${issueCount} preference issues\n` +
    `✅ Create automatic backup\n` +
    `✅ Apply optimal settings\n` +
    `✅ Restart Firefox and reopen this page\n\n` +
    `⚠️ Save any work in Firefox NOW!\n` +
    `⚠️ This page will close and reopen automatically.\n\n` +
    `Continue?`
  );

  if (!confirmed) return;

  setFixing(true);
  setResult(null);

  try {
    const response = await fetch("/api/auto-fix", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
    });

    const data = await response.json();

    if (!response.ok) {
      throw new Error(data.error || "Auto-fix failed");
    }

    setResult(data);
    showToast(`✅ Fixed ${data.issuesFixed} issues!`, "success", 5000);

    // Refresh preferences after fix
    if (onFixed) {
      setTimeout(onFixed, 1000);
    }
  } catch (error) {
    showToast(`❌ ${error.message}`, "error", 5000);
    setResult({ error: error.message });
  } finally {
    setFixing(false);
  }
};

const detectExternalPlayers = async () => {
  setLoadingPlayers(true);
  try {
    const response = await fetch("/api/external-players");
    const data = await response.json();
    setExternalPlayers(data);
  } catch (_error) {
    showToast("❌ Failed to detect external players", "error", 3000);
    // Set empty result on error so UI shows "no players found" instead of button
    setExternalPlayers({ players: [], count: 0, recommendation: "Install VLC or MPV for better video playback fallback" });
  } finally {
    setLoadingPlayers(false);
  }
};

// Auto-detect external players on component mount
useEffect(() => {
  detectExternalPlayers();
}, []);

/**
 * CLIPBOARD PASTE FUNCTION
 *
 * PURPOSE: Allow users to paste video URLs from clipboard with one click
 *
 * WHY:
 *  - Faster than manual paste (right-click video → copy URL → paste)
 *  - Better UX for users who copy URLs frequently
 *  - Reduces errors from partial URL paste
 *
 * BROWSER COMPATIBILITY:
 *  - Modern browsers: navigator.clipboard.readText()
 *  - Requires HTTPS or localhost (security requirement)
 *  - Falls back to manual paste if clipboard API unavailable
 */
const pasteFromClipboard = async () => {
  try {
    const text = await navigator.clipboard.readText();
    if (text.trim()) {
      setVideoUrl(text.trim());
      showToast("✅ URL pasted from clipboard", "success", 2000);
    } else {
      showToast("⚠️ Clipboard is empty", "warning", 2000);
    }
  } catch (error) {
    showToast("❌ Clipboard access denied. Use Ctrl+V to paste manually.", "error", 3000);
  }
};

/**
 * PLAY IN EXTERNAL PLAYER (ENHANCED WITH QUALITY SELECTION)
 *
 * PURPOSE: Stream or download video with user-selected quality
 *
 * QUALITY MODES:
 *  - auto: System automatically finds best quality that plays smoothly
 *  - 360p/480p/720p/1080p: User-selected fixed quality
 *
 * DOWNLOAD MODES:
 *  - stream: Instant playback (yt-dlp stdout → player stdin)
 *  - download: Download to temp file first, then play (shows progress + time estimate)
 *
 * WHY BOTH MODES:
 *  - Stream: Instant playback, no disk space, better for short videos
 *  - Download: Resumable, seekable, better for long videos or slow connections
 */

const playInExternalPlayer = async (player) => {
  if (!videoUrl.trim()) {
    showToast("❌ Please enter a video URL", "error", 3000);
    return;
  }

  setPlayingVideo(true);

try {
  const response = await fetch("/api/play-in-external-player", {
    method: "POST",
    headers: { "Content-Type": "application/json" },

body: JSON.stringify({
  url: videoUrl.trim(),
  player,
  quality,           // NEW: User-selected quality
  mode: downloadMode // NEW: stream vs download
}),

});

const data = await response.json();

if (!response.ok) {
  throw new Error(data.error || "Failed to launch player");
}

if (downloadMode === "download" && data.downloadId) {
  // Poll for download progress
  showToast(`📥 Downloading... (${quality})`, "info", 3000);
  pollDownloadProgress(data.downloadId);
} else {
  showToast(`✅ ${data.player} launched successfully! (${quality})`, "success", 3000);
  setVideoUrl(""); // Clear input after successful launch
}

} catch (error) {
  showToast(`❌ ${error.message}`, "error", 5000);
} finally {

if (downloadMode === "stream") {
  setPlayingVideo(false);
}

/**
 * POLL DOWNLOAD PROGRESS (FOR DOWNLOAD MODE)
 *
 * PURPOSE: Show real-time download progress with time estimates
 *
 * DISPLAYS:
 *  - Download percentage (0-100%)
 *  - Download speed (MB/s)
 *  - Time remaining (estimated)
 *  - File size (current / total)
 *
 * WHY:
 *  - User knows how long to wait
 *  - User can cancel if taking too long
 *  - Better UX than "Downloading..." with no feedback
 */
const pollDownloadProgress = (downloadId) => {
  const interval = setInterval(async () => {
    try {
      const response = await fetch(`/api/download-progress/${downloadId}`);
      const data = await response.json();

      setDownloadProgress(data);

      if (data.status === "complete") {
        clearInterval(interval);
        showToast(`✅ Download complete! Player launched.`, "success", 3000);
        setPlayingVideo(false);
        setVideoUrl("");
        setDownloadProgress(null);
      } else if (data.status === "error") {
        clearInterval(interval);
        showToast(`❌ Download failed: ${data.error}`, "error", 5000);
        setPlayingVideo(false);
        setDownloadProgress(null);
      }
    } catch (error) {
      clearInterval(interval);
      setPlayingVideo(false);
      setDownloadProgress(null);
    }
  }, 1000); // Poll every 1 second
};

