  </div>
  <p className="mode-hint">
    {downloadMode === "stream"
      ? "⚡ Stream: Instant playback, no disk space used"
      : "📥 Download: Shows progress + time estimate, fully seekable"}
  </p>
</div>

{/* DOWNLOAD PROGRESS (SHOWN WHEN DOWNLOADING) */}
