  let match;

  while ((match = regex.exec(content)) !== null) {
    const lang = match[1];
    const code = match[2];
    blocks.push({ lang, code });
    console.log(`[INFO] Extracted code block: ${lang} (${code.length} bytes)`);
  }

  return blocks;
}

// HELPER: Write code block to appropriate file
function writeCodeBlock(block, index) {
