 *   
 *   async function* myStream() {
 *     const wrapped = wrapAsyncIterator(originalStream);
 *     try {
 *       for await (const chunk of wrapped) {
 *         yield chunk;
 *       }
 *     } finally {
 *       await wrapped.return();
 *     }
