        const { stdout } = await execAsync(
            'ps aux | grep -E "(code|electron)" | grep -v grep'
        );

        const lines = stdout.trim().split('\n');
        for (const line of lines) {
            const parts = line.trim().split(/\s+/);
            if (parts.length < 11) continue;

            const pid = parseInt(parts[1], 10);
            const cpu = parseFloat(parts[2]);
            const mem = parseFloat(parts[3]);
            const cmd = parts.slice(10).join(' ');

            // Calculate memory in MB (mem is % of total)
            const memoryMB = (mem / 100) * totalMemory;

            // Only track zygote and extension host processes
            if (cmd.includes('--type=zygote') || cmd.includes('extensionHost') || cmd.includes('node.mojom.NodeService')) {
                processes.push({
                    pid,
                    name: cmd.substring(0, 100), // Truncate long command lines
                    cpu,
                    memory: memoryMB,
                    runtime: 0, // TODO: Parse from ps -o etime
                    cputime: 0  // TODO: Parse from ps -o cputime
                });
            }
        }
    } catch (err) {
        log(`Failed to get process metrics: ${err}`, 'WARN');
    }

    return {
        timestamp,
        totalMemory,
        usedMemory,
        freeMemory,
        swapTotal,
        swapUsed,
        loadAverage,
        processes
    };
}

