        const setFalseRefs: Array<{line: number, content: string}> = [];
        const cancelMsgRefs: Array<{line: number, content: string}> = [];

        for (let i = 0; i < lines.length; i++) {
            const line = lines[i];

            if (line.match(/_cancelledByUser/)) {
                cancelRefs.push({line: i + 1, content: line.trim()});

                // Check if setting to true
                if (line.match(/_cancelledByUser\s*=\s*(!0|true)/)) {
                    setTrueRefs.push({line: i + 1, content: line.trim()});
                }

                // Check if setting to false
                if (line.match(/_cancelledByUser\s*=\s*(!1|false)/)) {
                    setFalseRefs.push({line: i + 1, content: line.trim()});
                }
            }

            if (line.match(/Cancelled by user/)) {
                cancelMsgRefs.push({line: i + 1, content: line.trim()});
            }
        }

        // WHAT: Build diagnostic report
        // WHY: Need to show user the exact code causing the issue
        // HOW: Format findings into readable report
        let report = `CANCELLATION ROOT CAUSE ANALYSIS\n`;
        report += `Extension: ${augmentExtPath}\n\n`;

        report += `_cancelledByUser references: ${cancelRefs.length}\n`;
        cancelRefs.slice(0, 10).forEach(ref => {
            report += `  L${ref.line}: ${ref.content}\n`;
        });

        report += `\nSet to TRUE: ${setTrueRefs.length} locations\n`;
        setTrueRefs.forEach(ref => {
            report += `  L${ref.line}: ${ref.content}\n`;
        });

        report += `\nSet to FALSE: ${setFalseRefs.length} locations\n`;
        if (setFalseRefs.length === 0) {
            report += `  ✅ CONFIRMED: _cancelledByUser is NEVER reset to false (one-way latch)\n`;
        } else {
            setFalseRefs.forEach(ref => {
                report += `  L${ref.line}: ${ref.content}\n`;
            });
        }

        report += `\n"Cancelled by user" message: ${cancelMsgRefs.length} locations\n`;
        cancelMsgRefs.forEach(ref => {
            report += `  L${ref.line}: ${ref.content}\n`;
        });

        return report;

    } catch (err: any) {
        return `ERROR analyzing cancellation root cause: ${err.message}`;
    }
}

