// WHY: FD leak from getRemoteAgentOverviewsStream (803 AbortErrors) causes system instability
// HOW: Show warning with reload button when FD > 55000
// IMPACT: Prevents runaway zygotes and cancellation latch triggers
if (fdCount > 55000) {
