            context.report({
              node: info.node,
              messageId: "missingStderrHandler",
            });
          }

          if (!info.hasExitLogging) {
            context.report({
              node: info.node,
              messageId: "missingExitLogging",
            });
          }
        }
      },
    };
  },
};

